import type {RootComponents} from "./page_content.ts"

console.info(
    "%chi, js console users!\n" +
    "%ccheck 'debug' object for debugging options",
    "font-size: 2rem; background-color: #302040; color: #ddd; font-family: sans-serif; padding: 1rem; line-height: 3;",
    "font-size: 1rem; background-color: #604080; color: #ddd; padding: 0.5rem; line-height: 2;",
)

interface Debug {
    logASTs: boolean
    tokenize: (s: string) => any[]
    stackIt: (tok: any[]) => any[]
    runVM: (tok: any[], variables: Map<number, string | undefined>) => any
    root: RootComponents
}

const debugInterface: Partial<Debug> = {
    logASTs: false,
}

export default debugInterface;

declare global {
    interface Window {
        debug: typeof debugInterface
    }
}

window.debug = debugInterface