import type {rRecipe} from "./recipe_raw_types.d.ts"
import type {SimpleRecipeData} from "../simple/simple_types.ts"

// webstorm likes to assume you mean template literals `` when you type ${
// we don't want that, so this swaps in `@` instead
function l(strings: TemplateStringsArray, ...values: any[]): string {
    const result = strings.map(
        (value, index, arry) => index === arry.length - 1 ? value : value + values[index].toString()
    ).join("")
    return result.replace("@", "$")
}

