import type {IRecipeSelector, RecipeSelectorPage} from "../recipe_selector_types.d.ts"
import {html2, html2copy} from "../component_utilities.ts"
import type {RecipeCommon, SupportedRawTypes} from "../../library/recipe_raw_types.d.ts"
import {ICON_BACK, ICON_COPY, ICON_DELETE, ICON_EDIT, ICON_SHARE} from "../../page_content.ts"
import generateLink, {LIBRARY, Library, type LibraryCheckout} from "../../library/the_library.ts"
import {compileAndSetRecipe} from "../../runtime/recipe_runtime.ts"

const EDIT_SUPPORTED_TYPES: SupportedRawTypes["parser"][] = ["simple"]

const CONTENTS = html2(`<!---->
<dialog class="-confirm-deletion modal destructive" closedby="any">
    <h2>Confirm deletion</h2>
    <p>There's no undo button. You'll need to re-import this recipe to use it again.</p>
    <div class="-actions">
        <button class="-no">actually, no</button>
        <button class="destructive -yes">GET RID OF IT</button>
    </div>
</dialog>
<dialog class="-confirm-edit modal" closedby="any">
    <h2>Make a copy?</h2>
    <p>
        We need to copy the recipe before you can make changes.<br>
        The copy will be put into the "Custom recipes" section.
    </p>
    <div class="-actions">
        <button class="-no">No</button>
        <button class="constructive -yes">Yes</button>
    </div>
</dialog>
<dialog class="-export-dialog modal" closedby="any">
    <h2>Export & share</h2>
    <p>
        Take your pick.
    </p>
    <h3>Export as a file</h3>
    <div class="-actions">
        <button class="constructive -download">Download</button>
    </div>
    <h3>Shareable link</h3>
    <div class="-actions">
        <input class="-link" type="text" placeholder="https://...?" readonly>
        <button class="constructive -copy">Copy</button>
    </div>
    <div class="-actions -exit">
        <button>Done</button>
    </div>
</dialog>
<div class="recipe-viewer">
    <div class="-navbar">
        <button class="icon-button -back-button" title="go back"><img src="${ICON_BACK}" alt="Back"></button>
        <div class="spacer"></div>
        <button class="icon-button -share-button" title="share"><img src="${ICON_SHARE}" alt="Share"></button>
        <button class="icon-button -edit-button" title="edit"><img src="${ICON_EDIT}" alt="Edit"></button>
        <button class="icon-button -copy-button" title="duplicate"><img src="${ICON_COPY}" alt="Duplicate"></button>
        <button class="icon-button -delete-button" title="delete"><img src="${ICON_DELETE}" alt="Delete"></button>
        <button class="toolbar-button -select-button">Use</button>
    </div>
    <div class="-hero pop-in" style="--time-offset: .1s">
        <div class="-title-desc">
            <h1 class="-title">Title</h1>
            <h3><span class="-by-text">by</span> <span class="-author">Author</span></h3>
        </div>
    </div>
    <p class="-desc pop-in" style="--time-offset: .2s">
        Descriptive text
    </p>
    <p class="-desc2 pop-in" style="--time-offset: .3s">
        Descriptive text
    </p>
    <ul class="-stats pop-in" style="--time-offset: .5s">
        <li>recipe type: <span class="-parser">none</span></li>
        <li>version: <span class="-version">1234</span></li>
    </ul>
</div>
`)

export default class RecipeViewerPage implements RecipeSelectorPage {
    private recipeSel!: IRecipeSelector
    private recipe: RecipeCommon
    private readonly checkout: LibraryCheckout
    private container: HTMLElement
    private stats: HTMLElement
    private backBtn: HTMLButtonElement
    private selectBtn: HTMLButtonElement
    private shareBtn: HTMLButtonElement
    private editBtn: HTMLButtonElement
    private copyBtn: HTMLButtonElement
    private deleteBtn: HTMLButtonElement
    private deleteDialog: HTMLDialogElement
    private editDialog: HTMLDialogElement
    private exportDialog: HTMLDialogElement
    private exportDialogLink: HTMLInputElement
    private exportDialogLinkBtn: HTMLButtonElement

    constructor(container: HTMLElement, checkout: LibraryCheckout) {
        this.container = container
        this.recipe = checkout.data
        this.checkout = checkout

        this.stats = this.container.querySelector("ul.-stats") as HTMLElement

        this.backBtn = this.container.querySelector("button.-back-button") as HTMLButtonElement
        this.selectBtn = this.container.querySelector("button.-select-button") as HTMLButtonElement
        this.shareBtn = this.container.querySelector("button.-share-button") as HTMLButtonElement
        this.editBtn = this.container.querySelector("button.-edit-button") as HTMLButtonElement
        this.copyBtn = this.container.querySelector("button.-copy-button") as HTMLButtonElement
        this.deleteBtn = this.container.querySelector("button.-delete-button") as HTMLButtonElement

        this.deleteDialog = this.container.querySelector("dialog.-confirm-deletion") as HTMLDialogElement
        this.editDialog = this.container.querySelector("dialog.-confirm-edit") as HTMLDialogElement
        this.exportDialog = this.container.querySelector("dialog.-export-dialog") as HTMLDialogElement
        this.exportDialogLink = this.exportDialog.querySelector("input.-link") as HTMLInputElement
        this.exportDialogLinkBtn = this.exportDialog.querySelector("input.-link + button") as HTMLButtonElement

        this.fillInData()
    }

    teardown(): void {
    }

    fillInData() {
        const titleEl = this.container.querySelector(".-title") as HTMLElement
        titleEl.innerText = this.recipe.name
        const authorEl = this.container.querySelector(".-author") as HTMLElement
        authorEl.innerText = this.recipe.author ?? "(unknown)"
        const descEl = this.container.querySelector(".-desc") as HTMLElement
        descEl.innerText = this.recipe.shortDescription ?? ""
        descEl.hidden = !this.recipe.shortDescription
        const desc2El = this.container.querySelector(".-desc2") as HTMLElement
        desc2El.innerText = this.recipe.longDescription ?? ""
        const parserEl = this.container.querySelector(".-parser") as HTMLElement
        parserEl.innerText = this.recipe.parser
        const versionEl = this.container.querySelector(".-version") as HTMLElement
        versionEl.innerText = this.recipe.version.toString()

        const addStat = (text: string) => {
            const el = document.createElement("li")
            el.innerText = text
            this.stats.appendChild(el)
        }

        const category = LIBRARY.index.get(this.checkout.checkout.key)
        if (category) switch (category) {
            case "builtin":
                addStat("this recipe is built in to fumux")
                break
            case "temporary":
                addStat("this recipe is temporarily imported from the data included in the share link. to keep it, edit it or make a copy.")
        }

        const canEdit = (EDIT_SUPPORTED_TYPES as string[]).includes(this.recipe.parser)
        this.editBtn.hidden = !canEdit
        this.copyBtn.hidden = !(this.checkout.checkout.canEditInPlace || !canEdit)
        this.deleteBtn.hidden = !this.checkout.checkout.canDelete
    }

    attach(parent: IRecipeSelector): void {
        this.recipeSel = parent
        this.backBtn.addEventListener("click", () => {
            this.recipeSel.back()
        })

        this.deleteBtn.addEventListener("click", () => {
            this.deleteDialog.showModal()
        })

        this.deleteDialog.querySelector("button.-no")
            ?.addEventListener("click", () => this.deleteDialog.close())
        this.deleteDialog.querySelector("button.-yes")
            ?.addEventListener("click", () => {
                LIBRARY.delete(this.checkout)
                LIBRARY.save()
                this.recipeSel.back()
            })

        this.copyBtn.addEventListener("click", () => {
            const copied = LIBRARY.duplicate(this.checkout)
            copied.data.name = copied.data.name.replace(/\((\d+)\)$|$/, (_, n) => n ? `(${+n + 1})` : " (1)")
            LIBRARY.update(copied)
            LIBRARY.save()
            this.recipeSel.openViewer(copied, true)
        })

        this.selectBtn.addEventListener("click", () => {
            compileAndSetRecipe(this.checkout.data)
            this.recipeSel.close()
        })

        this.editBtn.addEventListener("click", () => {
            if (this.checkout.checkout.canEditInPlace) {
                this.recipeSel.openSimpleEdit(this.checkout, true)
            } else {
                this.editDialog.showModal()
            }
        })
        this.editDialog.querySelector("button.-no")
            ?.addEventListener("click", () => this.editDialog.close())
        this.editDialog.querySelector("button.-yes")
            ?.addEventListener("click", () => {
                const copied = LIBRARY.duplicate(this.checkout)
                copied.data.name = copied.data.name.replace(/\((\d+)\)$|$/, (_, n) => n ? `(${+n + 1})` : " (1)")
                LIBRARY.update(copied)
                LIBRARY.save()
                this.recipeSel.openSimpleEdit(copied, true)
            })

        this.exportDialog.querySelector(".-exit button")
            ?.addEventListener("click", () => {
                this.exportDialog.close()
            })

        this.shareBtn.addEventListener("click", () => {
            this.exportDialogLink.value = ""
            this.exportDialogLinkBtn.disabled = true
            this.exportDialog.showModal()
            generateLink(this.checkout)
                .then(params => {
                    const url = new URL(document.location.href)
                    Array.from(url.searchParams.keys()).forEach(it => url.searchParams.delete(it))
                    params.keys().forEach(it => url.searchParams.set(it, params.get(it)!))

                    this.exportDialogLink.value = url.toString()
                    this.exportDialogLinkBtn.disabled = false
                })
        })
        const copyBtn = this.exportDialog.querySelector("button.-copy")!
        copyBtn.addEventListener("click", async () => {
            copyBtn.textContent = "..."
            await navigator.clipboard.writeText(this.exportDialogLink.value)
            copyBtn.textContent = "✓"
            await new Promise(resolve => setTimeout(resolve, 1000))
            copyBtn.textContent = "Copy"
        })
        const downloadBtn = this.exportDialog.querySelector("button.-download")!
        downloadBtn.addEventListener("click", async () => {
            const file = JSON.stringify(this.checkout.data, null, 2)
            const blob = new Blob([file], {type: "application/json"})
            const link = document.createElement("a")
            const obj = URL.createObjectURL(blob)
            link.href = obj
            link.download = this.recipe.name.replace(/[^a-zA-Z0-9_.-]+/, '-') + ".json"
            link.style.display = "none"
            document.body.appendChild(link)
            link.click()
            link.remove()
            URL.revokeObjectURL(obj)
        })
    }

    static conjureVariant(slot: HTMLElement, checkout: LibraryCheckout) {
        const actualElement = html2copy(CONTENTS)
        const parent = slot.parentElement
        if (!parent) throw new Error("Slot is unparented, cannot expand elements")
        slot.replaceWith(...actualElement)
        return new RecipeViewerPage(parent, checkout)
    }

    // this should not be used in practice
    static conjure(slot: HTMLElement) {
        return RecipeViewerPage.conjureVariant(slot, Library.ERROR_CHECKOUT)
    }
}