import type {SupportedRawTypes} from "./recipe_raw_types.d.ts"
import {BUILT_IN_RECIPE_ORDER, BUILT_IN_RECIPES} from "./builtin_recipes.ts"
import {SimpleNotification} from "../notifs.ts"
import {ICON_CHECK, ICON_ERROR} from "../page_content.ts"
import {compileAndSetRecipe, setRecipe} from "../runtime/recipe_runtime.ts"
import compile from "./recipe_compilers.ts"

export type LibraryCategory = "created" | "imported" | "builtin" | "temporary"

type LibraryV1 = Partial<{
    libraryVersion: 1
    created: SupportedRawTypes[]
    imported: SupportedRawTypes[]
}>

export interface LibraryCheckoutInfo {
    canEditInPlace: boolean
    canDelete: boolean

    key: string
    shareSpecial?: string
}

export interface LibraryCheckout {
    data: SupportedRawTypes,
    checkout: LibraryCheckoutInfo
}

const localStorageKey = "library"

const nullUUID = "00000000-0000-0000-0000-000000000000"

export class Library {
    readonly localStorageKey = localStorageKey

    index: Map<string, LibraryCategory> = new Map()
    temporary: Map<string, SupportedRawTypes> = new Map()
    created: Map<string, SupportedRawTypes> = new Map()
    createdOrdering: string[] = []
    imported: Map<string, SupportedRawTypes> = new Map()
    importedOrdering: string[] = []
    builtin: Map<string, SupportedRawTypes> = new Map()
    builtinOrdering: string[] = []
    builtinUniqueNames: Map<string, string> = new Map()

    private locked: boolean = false

    static readonly ERROR_CHECKOUT: LibraryCheckout = {
        data: {
            name: "Something's broken!!",
            author: "debugging witch <3",
            shortDescription: "Oh no.",
            longDescription: "this is the default value. if you're seeing this, either the website is " +
                "lagging really hard, or something really broke. you should probably go back (or " +
                "whichever action gets you out of this situation.)",
            parser: "error",
            version: -1
        },
        checkout: {
            canEditInPlace: false,
            canDelete: false,
            key: nullUUID
        }
    }

    private static newCheckout(data: SupportedRawTypes, id: string, category: LibraryCategory): LibraryCheckout {
        return {
            checkout: {
                key: id,
                canDelete: category !== "builtin" && category !== "temporary",
                canEditInPlace: category === "created",
                shareSpecial: category === "builtin" ? data.uniqueName : undefined
            },
            data: structuredClone(data)
        }
    }

    createNew(data: SupportedRawTypes, category: LibraryCategory): string {
        if (this.locked && category === "builtin") throw new Error("you can't create new built-in recipes.")
        let id = crypto.randomUUID()
        while (this.index.has(id)) id = crypto.randomUUID()
        switch (category) {
            case "created":
                this.created.set(id, data)
                this.createdOrdering.push(id)
                break
            case "imported":
                this.imported.set(id, data)
                this.importedOrdering.push(id)
                break
            case "builtin":
                this.builtin.set(id, data)
                this.builtinOrdering.push(id)
                break
            case "temporary":
                this.temporary.set(id, data)
        }
        this.index.set(id, category)
        return id
    }

    private loadBuiltins() {
        console.info(`load builtins (${BUILT_IN_RECIPE_ORDER.length}):`)
        for (const recipeName of BUILT_IN_RECIPE_ORDER) {
            console.info(" ", recipeName)
            const recipe = BUILT_IN_RECIPES[recipeName]
            const id = this.createNew(recipe, "builtin")
            if (recipe.uniqueName)
                this.builtinUniqueNames.set(recipe.uniqueName, id)
        }
        this.locked = true
    }

    constructor() {
        this.loadBuiltins()
    }

    updateDirect(key: string, newData: SupportedRawTypes): LibraryCheckout {
        const target = this.index.get(key)
        const needToCopy = !target || target !== "created"
        if (needToCopy) {
            const newID = this.createNew(newData, "created")
            return Library.newCheckout(newData, newID, "created")
        } else {
            this.created.set(key, newData)
            return Library.newCheckout(newData, key, "created")
        }
    }

    update(checkout: LibraryCheckout, newData?: SupportedRawTypes): LibraryCheckout {
        newData ||= checkout.data
        const id = checkout.checkout.key
        return this.updateDirect(id, newData)
    }

    duplicate(checkout: LibraryCheckout): LibraryCheckout {
        const clone = structuredClone(checkout.data)
        delete clone.uniqueName
        const newID = this.createNew(clone, "created")
        return Library.newCheckout(clone, newID, "created")
    }

    delete(checkout: LibraryCheckout) {
        const id = checkout.checkout.key
        const target = this.index.get(id)
        if (!target) return
        if (target === "builtin") return
        switch (target) {
            case "created":
                this.created.delete(id)
                break
            case "imported":
                this.imported.delete(id)
                break
        }
    }

    getByID(id: string): LibraryCheckout | undefined {
        const target = this.index.get(id)
        if (!target) return undefined
        let data: SupportedRawTypes | undefined
        switch (target) {
            case "created":
                data = this.created.get(id)
                break
            case "imported":
                data = this.imported.get(id)
                break
            case "builtin":
                data = this.builtin.get(id)
                break
            case "temporary":
                data = this.temporary.get(id)
                break
        }
        return data ? Library.newCheckout(data, id, target) : undefined
    }

    getAll() {
        this.checkConsistency()
        return {
            created: this.createdOrdering.map(it => Library.newCheckout(this.created.get(it)!, it, "created")),
            imported: this.importedOrdering.map(it => Library.newCheckout(this.imported.get(it)!, it, "imported")),
            builtin: this.builtinOrdering.map(it => Library.newCheckout(this.builtin.get(it)!, it, "builtin")),
            temporary: this.temporary.entries().map(([k, v]) => Library.newCheckout(v, k, "temporary")).toArray(),
        }
    }

    checkConsistency() {
        this.createdOrdering = this.createdOrdering.filter(it => this.created.has(it))
        this.importedOrdering = this.importedOrdering.filter(it => this.imported.has(it))
        this.createdOrdering.push(...this.created.keys().filter(it => !this.createdOrdering.includes(it)))
        this.importedOrdering.push(...this.imported.keys().filter(it => !this.importedOrdering.includes(it)))
    }

    export(): LibraryV1 {
        this.checkConsistency()
        return {
            libraryVersion: 1 as const,
            created: this.createdOrdering.map(it => this.created.get(it)!),
            imported: this.importedOrdering.map(it => this.imported.get(it)!)
        }
    }

    save() {
        const raw = JSON.stringify(this.export())
        console.info(`Library saved. ${raw.length} bytes (JSON).`)
        localStorage.setItem(localStorageKey, raw)
    }

    static load(data: { [k: string]: any }): Library | undefined {
        switch (data.libraryVersion) {
            case 1:
                return Library.loadv1(data)
        }
    }

    static loadv1(data: LibraryV1): Library {
        const result = new Library()
        if (data.created)
            for (const item of data.created)
                result.createNew(item, "created")
        if (data.imported)
            for (const item of data.imported)
                result.createNew(item, "created")
        return result
    }

    getBuiltin(reference: string): string | undefined {
        return this.builtinUniqueNames.get(reference)
    }
}

export const LIBRARY = ((): Library => {
    const dataRaw = localStorage.getItem(localStorageKey)
    if (!dataRaw) return new Library()
    const obj = JSON.parse(dataRaw)
    if (!obj || !(obj instanceof Object)) {
        console.warn(`invalid library data (discarding):`, obj)
        return new Library()
    }
    const imported = Library.load(obj)
    if (!imported) {
        console.warn(`invalid library data (discarding):`, obj)
        return new Library()
    }
    console.info("loaded library from storage successfully")
    return imported
})()

console.info("writing library for the first time")
LIBRARY.save()

const RAW_IMPORT_Q = "i"
const BUILTIN_REF_Q = "builtin"

export default async function generateLink(checkout: LibraryCheckout): Promise<URLSearchParams> {
    const builtInName = checkout.checkout.shareSpecial
    if (builtInName) return new URLSearchParams([[BUILTIN_REF_Q, builtInName]])
    const json = JSON.stringify(checkout.data)
    const raw = new TextEncoder().encode(json)
    const compressed = new CompressionStream("deflate")
    const writer = compressed.writable.getWriter()
    void writer.write(raw)
    void writer.close()
    const fakeResp = new Response(compressed.readable)
    const output = await fakeResp.bytes()
    return new URLSearchParams([
        [RAW_IMPORT_Q, output.toBase64({alphabet: "base64url"})]
    ])
}

export async function loadFromURL() {
    const query = new URLSearchParams(document.location.search)
    if (query.has(BUILTIN_REF_Q)) {
        const reference = query.get(BUILTIN_REF_Q)!
        const actualId = LIBRARY.getBuiltin(reference)
        if (!actualId) {
            const errorNotif = new SimpleNotification(ICON_ERROR, "Import failed").make()
            errorNotif.setTextTainted(`Import failed: builtin unique name ${reference} not found.`)
            setTimeout(() => errorNotif.remove(), 2000)
        } else {
            const recipe = LIBRARY.getByID(actualId)!
            if (compileAndSetRecipe(recipe.data)) {
                const ok = new SimpleNotification(ICON_CHECK, "Loaded").make()
                ok.setTextTainted(`Loaded '${recipe.data.name}'`)
                setTimeout(() => ok.remove(), 1000)
            }
            return
        }
    }
    if (query.has(RAW_IMPORT_Q)) {
        const raw = query.get(RAW_IMPORT_Q)!
        try {
            const bytes = Uint8Array.fromBase64(raw, { alphabet: "base64url" })
            const decompress = new DecompressionStream("deflate")
            const writer = decompress.writable.getWriter()
            void writer.write(bytes)
            void writer.close()
            const fakeResp = new Response(decompress.readable)
            const output = await fakeResp.text()
            const data = JSON.parse(output)
            console.info(data)
            const compiled = compile(data)
            LIBRARY.createNew(data as SupportedRawTypes, "temporary")
            setRecipe(compiled)
            const ok = new SimpleNotification(ICON_CHECK, "Loaded").make()
            ok.setTextTainted(`Loaded '${data.name}'`)
            setTimeout(() => ok.remove(), 1000)
        } catch (e) {
            const errorNotif = new SimpleNotification(ICON_ERROR, "Import failed").make()
            errorNotif.setTextTainted(`Import failed: ${e}`)
            setTimeout(() => errorNotif.remove(), 2000)
        }
    }
}