// the replacer
// handles <x-replace>

import ArgumentEditor from "./argument_editor.ts"
import RecipeSelector from "./recipe_selector.ts"
import PageRoot from "./editor/root.ts"
import PageSimpleEdit from "./editor/simple_edit.ts"
import PageRecipeViewer from "./editor/viewer.ts"
import {IOPanel} from "./io.ts"
import RecipeSelectorButton from "./recipe_selector_button.ts"

const understood: { [key: string]: (slot: HTMLElement) => Swappable } = {
    "argument-editor": ArgumentEditor.conjure,
    "io-panel": IOPanel.conjure,
    "recipe-selector": RecipeSelector.conjure,
    "page-root": PageRoot.conjure,
    "page-simple-edit": PageSimpleEdit.conjure,
    "page-viewer": PageRecipeViewer.conjure,
    "recipe-selector-button": RecipeSelectorButton.conjure,
}

export function createReplaceTag(type: string, name: string): HTMLElement {
    const el = document.createElement("x-replace")
    el.setAttribute("type", type)
    el.setAttribute("name", name)
    return el
}

export default function (el: HTMLElement) {
    const replacements = el.querySelectorAll("x-replace")
    const results: Map<string, Swappable | Swappable[]> = new Map()
    for (const slot of replacements) {
        if (!(slot instanceof HTMLElement)) continue
        const typeName = slot.getAttribute("type")
        if (!typeName) throw new TypeError(`x-replace with missing type ${slot}`)
        const fn = understood[typeName]
        if (!fn) throw new TypeError(`x-replace with unknown type ${typeName}`)
        const result = fn(slot)

        const name = slot.getAttribute("name")
        if (name) {
            if (results.get(name)) throw new ReferenceError(`x-replace duplicate name ${name}`)
            results.set(name, result)
        }
        const list = slot.getAttribute("list")
        if (list) {
            let theList = results.get(list)
            if (!theList) theList = []
            if (!(theList instanceof Array)) throw new TypeError(`x-replace uses ${list} as a list but it's already a unique name`)
            theList.push(result)
            results.set(list, theList)
        }
    }

    return results
}