/** the mathematical expression parser, based on the https://en.wikipedia.org/wiki/Shunting_yard_algorithm */
import debugInterface from "../debug_interface.ts"

type UnaryOperators = "not" | "neg"
type BinaryOperators =
    "add"
    | "sub"
    | "mul"
    | "div"
    | "eq"
    | "neq"
    | "gt"
    | "ge"
    | "lt"
    | "le"
    | "concat"
    | "and"
    | "or"
type Values = "number" | "string" | "variable" | "ifdef" | "ifndef" | "true" | "false"
type Misc = "error" | "left_par" | "right_par"

type TokenType = UnaryOperators | BinaryOperators | Values | Misc

interface ExprTok {
    kind: TokenType
    lexeme: string
    value: number | boolean | string | null
}

const validNumericStarters = Array.from("0123456789.")

// Oh, a SECOND parser? in my web app? wtf?
function tokenize(input: string): ExprTok[] {
    let c = 0
    const result: ExprTok[] = []

    function read(): string {
        return input.charAt(c++)
    }

    function peek(): string {
        return input.charAt(c)
    }

    function peek2(): string {
        return input.charAt(c + 1)
    }

    function match(char: string | RegExp) {
        const matches = char instanceof RegExp ? !!char.exec(peek()) : peek() === char
        if (matches) {
            read()
            return true
        }
        return false
    }

    let begin = 0

    function tA(type: TokenType) {
        result.push({
            kind: type,
            lexeme: input.substring(begin, c),
            value: null,
        })
        begin = c
    }

    const readNumber = () => {
        begin = c
        // sign?
        match("-")
        // 0 or more digits, then a decimal & 1 digit OR 1 or more digits
        let needFractional = false
        lhs: {
            if (match(".")) {
                needFractional = true
                break lhs
            }
            while (match(/[0-9]/)) {
            }
            match(".")
        }
        if (needFractional) {
            if (!match(/[0-9]/)) return tA("error")
        }
        while (match(/[0-9]/)) {
        }
        if (match(/[eE]/)) {
            match(/[+-]/)
            if (!match(/[0-9]/)) return tA("error")
            while (match(/[0-9]/)) {
            }
        }
        const whole = input.substring(begin, c)

        result.push({
            kind: "number",
            lexeme: whole,
            value: parseFloat(whole),
        })
        begin = c
    }

    const dedicatedToken = (token: TokenType) => () => {
        begin = c
        read()
        tA(token)
    }

    const firstCharacter: { [char: string]: () => void | undefined } = {
        "!": () => {
            begin = c
            read()
            if (peek() === "=") {
                read()
                return tA("neq")
            }
            tA("not")
        },
        "-": () => {
            if (validNumericStarters.includes(peek2())) {
                return readNumber()
            }
            begin = c
            read()
            tA("neg")
        },
        "+": dedicatedToken("add"),
        "*": dedicatedToken("mul"),
        "/": dedicatedToken("div"),
        "(": dedicatedToken("left_par"),
        ")": dedicatedToken("right_par"),
        "&": () => {
            begin = c
            read()
            if (match("&")) tA("and")
            else tA("concat")
        },
        ">": () => {
            begin = c
            read()
            if (match("=")) tA("ge")
            else tA("gt")
        },
        "<": () => {
            begin = c
            read()
            if (match("=")) tA("le")
            else tA("lt")
        },
        "=": () => {
            begin = c
            read()
            if (!match("=")) tA("error")
            else tA("eq")
        },
        "|": () => {
            begin = c
            read()
            if (!match("|")) tA("error")
            else tA("or")
        },
        "$": () => {
            begin = c
            read()
            let type: TokenType = "variable"
            if (match("?")) type = "ifdef"
            else if (match("!")) type = "ifndef"
            const begin2 = c
            if (!match(/[0-9]/)) return tA("error")
            while (match(/[0-9]/)) {
            }
            const index = parseInt(input.substring(begin2, c))

            result.push({
                kind: type,
                lexeme: input.substring(begin, c),
                value: index,
            })
            begin = c
        },
    } as const

    const specials: { when: RegExp, action: (matchData: RegExpMatchArray) => void }[] = [
        {
            when: /\s/y,
            action: () => {
                read()
                begin = c
            }
        },
        {
            when: /[0-9]/y,
            action: readNumber
        },
        {
            when: /(['"])\1*/y,
            action: (match) => {
                begin = c
                const endToken = match[0]
                const endMatcher = new RegExp(endToken, "y")
                for (let i = 0; i < endToken.length; i++) read()
                const textBegin = c
                while (c < input.length) {
                    endMatcher.lastIndex = c
                    if (endMatcher.test(input)) break
                    read()
                }
                const text = input.substring(textBegin, c)
                for (let i = 0; i < endToken.length; i++) read()
                if (c > input.length) return tA("error")

                result.push({
                    kind: "string",
                    lexeme: input.substring(begin, c),
                    value: text,
                })
                begin = c
            }
        },
        {
            when: /(?:true|false)(?=[^\w0-9_]|$)/y,
            action: (match) => {
                begin = c
                for (let i = 0; i < match[0].length; i++) read()
                tA(match[0] as "true" | "false")
            }
        },
        {
            when: /./y,
            action: res => {
                throw new Error(`unparsable '${res[0]}' at position ${c} (around '${input.substring(c, c + 16)}')`)
            }
        }
    ]

    let lastC = -1
    while (c < input.length) {
        if (c === lastC) throw new Error(`did not advance parser on position ${c} (this is a bug.)`)
        lastC = c
        const matched = firstCharacter[peek()]
        if (matched) {
            matched()
            continue
        }
        specials.find(it => {
            it.when.lastIndex = c
            const result = it.when.exec(input)
            if (result) {
                it.action(result)
                return true
            }
            return false
        })
    }
    return result
}

const precedence: { [key in TokenType]: number } = {
    string: -1,
    number: -1,
    variable: -1,
    ifdef: -1,
    ifndef: -1,
    error: -1,
    true: -1,
    false: -1,
    and: 0,
    or: 0,
    eq: 1,
    neq: 1,
    gt: 1,
    ge: 1,
    lt: 1,
    le: 1,
    add: 2,
    sub: 2,
    mul: 3,
    div: 3,
    concat: 4,
    not: 5, // !1 + 1
    neg: 5, // 2 * -$1 + 2
    left_par: -2,
    right_par: -2
}
const metatypes: { [key in TokenType]: "binary" | "unary" | "value" | "misc" } = {
    string: "value",
    number: "value",
    variable: "value",
    ifdef: "value",
    ifndef: "value",
    error: "value",
    true: "value",
    false: "value",
    not: "unary",
    neg: "unary",
    add: "binary",
    sub: "binary",
    mul: "binary",
    div: "binary",
    eq: "binary",
    neq: "binary",
    gt: "binary",
    ge: "binary",
    lt: "binary",
    le: "binary",
    and: "binary",
    or: "binary",
    concat: "binary",
    left_par: "misc",
    right_par: "misc"
}

function stackIt(tokens: ExprTok[]): ExprTok[] {
    const rpn: ExprTok[] = []
    const opStack: ExprTok[] = []

    for (const token of tokens) {
        if (token.kind === "error") throw new Error(`encountered error token: '${token.lexeme}'`)
        if (metatypes[token.kind] === "value") {
            rpn.push(token)
            let top: ExprTok | undefined
            while ((top = opStack[opStack.length - 1]) && metatypes[top.kind] === "unary") {
                rpn.push(opStack.pop()!)
            }
            continue
        }
        if (token.kind === "left_par") {
            opStack.push(token)
            continue
        }
        if (token.kind === "right_par") {
            while (opStack.length > 0) {
                const removed = opStack.pop()!
                if (removed.kind === "left_par") break
                rpn.push(removed)
            }
            let top: ExprTok | undefined
            while ((top = opStack[opStack.length - 1]) && metatypes[top.kind] === "unary") {
                rpn.push(opStack.pop()!)
            }
            continue
        }
        if (metatypes[token.kind] === "unary") {
            opStack.push(token)
            continue
        }

        // All operators
        while (true) {
            const type = opStack[opStack.length - 1]?.kind
            if (!type) break
            if (precedence[type] >= precedence[token.kind]) {
                rpn.push(opStack.pop()!)
            } else break
        }
        opStack.push(token)
    }
    let token: ExprTok | undefined
    while (token = opStack.pop()) {
        if (token.kind === "left_par") throw new Error(`unbalanced parentheses`)
        rpn.push(token)
    }

    return rpn
}

function runVM(rpn: ExprTok[], variables: Map<number, string | undefined>): string | number | boolean | undefined {
    const stack: (string | number | boolean | undefined)[] = []

    function binary(): [string | number | boolean | undefined, string | number | boolean | undefined] {
        if (stack.length < 2) throw new Error("stack vm: not enough values for binary operator")
        const right = stack.pop()
        const left = stack.pop()
        return [left, right]
    }

    function unary(): string | number | boolean | undefined {
        if (stack.length < 1) throw new Error("stack vm: not enough values for unary operator")
        return stack.pop()
    }

    const opcodes: { [key in TokenType]: (tok: ExprTok) => void } = {
        error(tok: ExprTok) {
        },
        left_par(tok: ExprTok) {
        },
        right_par(tok: ExprTok) {
        },
        true() {
            stack.push(true)
        },
        false() {
            stack.push(false)
        },
        number(tok) {
            stack.push(tok.value as number)
        },
        string(tok) {
            stack.push(tok.value as string)
        },
        variable(tok) {
            const value = variables.get(tok.value as number)
            // try to coerce numbers to the right type
            if (value !== undefined && value.length > 0 && !isNaN(+value)) {
                stack.push(+value)
            } else {
                stack.push(value)
            }
        },
        ifdef(tok) {
            stack.push(
                variables.has(tok.value as number) && variables.get(tok.value as number) !== undefined
            )
        },
        ifndef(tok) {
            stack.push(
                !(variables.has(tok.value as number) && variables.get(tok.value as number) !== undefined)
            )
        },
        not() {
            stack.push(!unary())
        },
        neg() {
            const value = unary()
            if (value === undefined) throw new Error("can't coerce unary negation rhs to number because it is undefined")
            const result = -+value
            if (isNaN(result)) throw new Error("unary negation resulted in NaN")
            stack.push(result)
        },
        add() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of + to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of + to number because it is undefined")
            const result = (+lhs) + (+rhs)
            if (isNaN(result)) throw new Error("result of + is not a number")
            stack.push(result)
        },
        sub() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of - to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of - to number because it is undefined")
            const result = (+lhs) - (+rhs)
            if (isNaN(result)) throw new Error("result of - is not a number")
            stack.push(result)
        },
        mul() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of * to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of * to number because it is undefined")
            const result = (+lhs) * (+rhs)
            if (isNaN(result)) throw new Error("result of * is not a number")
            stack.push(result)
        },
        div() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of / to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of / to number because it is undefined")
            const result = (+lhs) / (+rhs)
            if (isNaN(result)) throw new Error("result of / is not a number (div. by zero?)")
            stack.push(result)
        },
        eq() {
            const [lhs, rhs] = binary()
            // Strict equality. Some types may not be handled correctly.
            stack.push(lhs === rhs)
        },
        neq() {
            const [lhs, rhs] = binary()
            stack.push(lhs !== rhs)
        },
        gt() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of > to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of > to number because it is undefined")
            stack.push(+lhs > +rhs)
        },
        ge() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of >= to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of >= to number because it is undefined")
            stack.push(+lhs >= +rhs)
        },
        lt() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of < to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of < to number because it is undefined")
            stack.push(+lhs < +rhs)
        },
        le() {
            const [lhs, rhs] = binary()
            if (lhs === undefined) throw new Error("can't coerce lhs of <= to number because it is undefined")
            if (rhs === undefined) throw new Error("can't coerce rhs of <= to number because it is undefined")
            stack.push(+lhs <= +rhs)
        },
        concat() {
            const [lhs, rhs] = binary()
            stack.push(`${lhs}${rhs}`)
        },
        and() {
            const [lhs, rhs] = binary()
            stack.push(lhs && rhs)
        },
        or() {
            const [lhs, rhs] = binary()
            stack.push(lhs || rhs)
        }
    }

    for (const op of rpn) {
        opcodes[op.kind]?.(op)
    }
    if (stack.length !== 1) {
        console.error("the stack isn't clean:", stack)
    }
    return stack.pop()
}

export function compileAndExecuteExpr(code: string, variables: Map<number, string | undefined>): string | number | boolean | undefined {
    return runVM(stackIt(tokenize(code)), variables)
}

debugInterface.tokenize = tokenize
debugInterface.stackIt = stackIt
debugInterface.runVM = runVM