const containerI = html1(container)
type AstAnnotation = "plain" | "esc" | "var" | "var-unknown" | "str-1" | "str-2" | "argument" | "root" | "error"

interface ShellAstNode {
    target: Text | null
    begin: number
    end: number

    isStandalone: boolean
    annotation: AstAnnotation
    content: string | null
    children: ShellAstNode[]
}

type PartialShellAstNode = Omit<ShellAstNode, "end" | "children"> & {
    end?: number
    children: PartialShellAstNode[]
}

const quotes = Object.freeze({
    "'": "str-1",
    '\"': "str-2"
})

type ParserState = "none" | "argument" | "string" | "plain" | "variable"

interface ParserResult {
    nodes: ShellAstNode[]
    error: boolean
}

const awkwardSpaces = /(?![ \t\u00A0])\s/

class ShellSyntax {
    private vars: string[]

    constructor(vars: string[]) {
        this.vars = vars
    }

    private static findLeaves(node: ChildNode): ChildNode[] {
        const leaves = []
        const frontier = [node]

        let next: ChildNode | undefined
        while (next = frontier.pop()) {
            if (next.childNodes.length === 0) leaves.push(next)
            else frontier.push(...next.childNodes)
        }

        return leaves
    }

    // you ever just. make a state machine lexer/parser?
    parseText2(node: Text): ParserResult {
        const _this: ShellSyntax = this

        const finished: ShellAstNode[] = []
        const open: PartialShellAstNode[] = []

        const text = node.wholeText
        let cursor = 0

        function peekN(): PartialShellAstNode | undefined {
            return open[open.length - 1]
        }

        function pushN(type: AstAnnotation, position: number) {
            const last = peekN()
            const next: PartialShellAstNode = {
                annotation: type,
                begin: position,
                children: [],
                target: node,
                isStandalone: !last,
                content: null
            }
            last?.children?.push(next)
            open.push(next)
        }

        function retypeN(type: AstAnnotation) {
            const last = peekN()
            if (!last) throw new Error("retype node (no node to retype)")
            last.annotation = type
        }

        function endN(endPosition: number, content: string | null) {
            const last = open.pop()
            if (!last) throw new Error("finish node (no node to finish)")
            last.end = endPosition
            last.content = content
            finished.push(last as ShellAstNode)
        }

        function captureEndN(endPos: number) {
            const last = peekN()
            if (!last) return
            const content = text.substring(last.begin, endPos).replaceAll("\u00A0", " ")
            return endN(endPos, content)
        }

        function isEOF() {
            return cursor >= text.length
        }

        function read(): string {
            if (isEOF()) return '\0'
            return text.charAt(cursor++)
        }

        function undo() {
            if (cursor <= 0) throw new Error('at start of buffer, cannot undo')
            cursor--
        }

        function peek(): string {
            if (isEOF()) return '\0'
            return text.charAt(cursor)
        }

        function rpeek(): string {
            undo()
            return read()
        }

        function match(strOrRegExp: string | RegExp): boolean {
            if (strOrRegExp instanceof RegExp) {
                if (peek().match(strOrRegExp)) {
                    read()
                    return true
                }
                return false
            }
            if (peek() === strOrRegExp) {
                read()
                return true
            }
            return false
        }

        function peekMatch(strRegExp: string | RegExp) {
            if (match(strRegExp)) {
                undo()
                return true
            }
            return false
        }

        const state: ParserState[] = ["none"]
        let quoteKind: "'" | '"' | null = null
        let varAccumulator = ""

        function pushS(s: ParserState) {
            state.push(s)
        }

        function rts() {
            if (state.length === 0) throw new Error("oh no you returned too many times there are no more states")
            state.pop()
        }

        // return true if any characters consumed
        function dollarSign(): boolean {
            const before = cursor
            if (match("$")) {
                if (match("$")) {
                    pushN("esc", before)
                    captureEndN(cursor)
                    return true
                }
                if (match("{")) {
                    varAccumulator = ""
                    pushN("var", before)
                    pushS("variable")
                    return true
                }
                return true
            }
            return false
        }

        // noinspection JSUnusedGlobalSymbols
        const sm: { [state in ParserState]: () => void } = {
            none: () => {
                if (isEOF()) return rts() // exit
                if (match(/\s/)) return

                // to argument
                pushN("argument", cursor)
                return pushS("argument")
            },
            argument: () => {
                const before = cursor
                if (match(/['"]/)) {
                    quoteKind = rpeek() as "'" | '"'
                    pushN(quotes[quoteKind], before)
                    return pushS("string")
                }
                if (match(/\s/) || isEOF()) {
                    captureEndN(before)
                    return rts()
                }
                pushN("plain", before)
                return pushS("plain")
            },
            string: () => {
                const supportsVars = quoteKind === '"'
                if (match(quoteKind!)) {
                    const thisStr = peekN()!
                    const content = text.substring(thisStr.begin + 1, cursor - 1)
                    endN(cursor, content)
                    return rts()
                }
                if (supportsVars && dollarSign()) return
                if (peekMatch(awkwardSpaces) || isEOF()) {
                    retypeN("error")
                    endN(cursor, null)
                    return rts()
                }
                read()
            },
            plain: () => {
                // string or space boundary
                if (peekMatch(/[\s'"]/) || isEOF()) {
                    captureEndN(cursor)
                    return rts()
                }
                if (dollarSign()) return
                read()
            },
            variable: () => {
                if (match("}")) {
                    if (!_this.vars.includes(varAccumulator)) retypeN("var-unknown")
                    endN(cursor, varAccumulator)
                    return rts()
                }
                if (match("{") || peekMatch(awkwardSpaces) || isEOF()) {
                    retypeN("error")
                    endN(cursor, null)
                    return rts()
                }
                varAccumulator += read().replaceAll("\u00A0", " ")
            }
        }

        let steps = 0
        while (state.length > 0 && ++steps < 100_000) sm[state[state.length - 1]!]()
        // this really shouldn't happen, but just in case...
        while (open.length > 0) {
            console.error(`something really went wrong with the syntax parser.`, peekN())
            retypeN("error")
            endN(text.length, null)
        }

        return {
            nodes: finished.filter(it => it.isStandalone),
            error: finished.some(it => it.annotation === "error")
        }
    }

    parseRoot(node: ChildNode) {
        const leaves = ShellSyntax.findLeaves(node)
        const nodes: ShellAstNode[] = []
        let hasAnyError = false
        for (const leaf of leaves) {
            if (leaf instanceof Text) {
                const parsed = this.parseText2(leaf)
                hasAnyError ||= parsed.error
                nodes.push({
                    begin: 0,
                    children: parsed.nodes,
                    content: null,
                    end: leaf.wholeText.length,
                    isStandalone: true,
                    target: leaf,
                    annotation: "root"
                })
            }
        }

        return {nodes, hasAnyError}
    }
}

//@ts-ignore
window.ShellSyntax = ShellSyntax

/**
 * find ast nodes of a certain type. **mutates `frontier`.**
 * @param frontier
 * @param type
 */
function findASTNodesByType<T extends AstAnnotation>(frontier: ShellAstNode[], type: T): ShellAstNode[] {
    const result: ShellAstNode[] = []

    let node: ShellAstNode | undefined
    while (node = frontier.pop()) {
        if (node.annotation === type) result.push(node)
        frontier.push(...node.children.toReversed())
    }

    return result
}

function stripArgListInput(messy: string): string {
    return messy
        .replaceAll(/^[\r\n\t]+|[\r\n\t]+$/g, "")
        .replaceAll(/[\r\n\t]+/g, " ")
}

export interface ArgumentEditorUpdateData {
    args: string[]
    shell: string
    shellPref: boolean
}

type ArgumentEditorOnChangeEvent = (data: ArgumentEditorUpdateData) => void

/**
 * at some point I need to learn React, y'all
 */
export default class ArgumentEditor implements Swappable {
    readonly wrap: HTMLElement

    private readonly shellInput: HTMLElement
    private readonly shellHighlighting: HTMLElement
    private readonly argListEl: HTMLOListElement

    private onChangedEvent: ArgumentEditorOnChangeEvent[] = []

    private prefShell = true

    readonly understoodVariables: string[] = []
    argumentList: string[] = []
    private shellText: string = ``

    constructor(wrap: HTMLElement) {
        this.wrap = wrap
        this.shellInput = wrap.querySelector(".-edit-stack-editor")!
        this.shellHighlighting = wrap.querySelector(".-edit-stack-graphics")!
        this.argListEl = wrap.querySelector(".-edit-arglist")!
        this.shellInput.innerText = this.shellText

        // Watch out for NBSPs in the input! Firefox likes to put those in there!

        this.updateShell(true)

        this.shellInput.addEventListener("input", () => {
            this.updateShell(true)
        })
        this.shellInput.addEventListener("paste", () => {
            this.updateShell(true)
        })

        // yeah this is hidden state, i don't care, it's a stupid <summary> link
        let isHelpOpen = false
        const helpLink = wrap.querySelector(".-help-link")!
        const helpText = wrap.querySelector(".-editor-help")!
        helpLink.addEventListener("click", e => {
            isHelpOpen = !isHelpOpen
            if (isHelpOpen) helpText.classList.remove("hidden")
            else helpText.classList.add("hidden")
            const flipper = helpLink.querySelector(".-show-hide") as HTMLElement
            flipper.innerText = isHelpOpen ? "Hide" : "Show"

            e.stopPropagation()
        })
    }

    private static stripBasicStyleElements(subject: HTMLElement) {
        subject.querySelectorAll("span, b, i, u, strike")
            .forEach(it => it.replaceWith(...it.childNodes))
    }

    private applyHighlighting(ast: ShellAstNode, container?: Text, containerBasis?: number): {
        node: Text,
        basis: number
    } {
        const target = container! || ast.target
        const basis = containerBasis! || 0
        const middle = target.splitText(ast.begin - basis)
        const after = middle.splitText(ast.end - ast.begin)
        const highlighter = document.createElement("span")
        middle.remove()
        highlighter.classList.add("-ast")
        highlighter.dataset.annotation = ast.annotation
        highlighter.appendChild(middle)
        target.after(highlighter)

        let myContainer = middle
        let myBasis = ast.begin
        for (const childAst of ast.children) {
            const {node, basis} = this.applyHighlighting(childAst, myContainer, myBasis)
            myContainer = node
            myBasis = basis
        }

        return {
            node: after,
            basis: ast.end
        }
    }

    private static convertAstToText(ast: ShellAstNode): string {
        const content = ast.content
        switch (ast.annotation) {
            case "plain":
            case "str-2":
                // replacement value syntax: $$ escapes a single $
                if (content!.match(/(^|[^$])\$$/))
                    return content!.replace(/\$$/, "$$$$")
                return content!
            case "str-1":
                return content!.replaceAll("$", "$$$$")

            case "var":
            case "var-unknown":
            case "esc":
                throw new Error("Cannot convert highlighting nodes (var, esc) to text; should be contained in content node (plain, str-2)")

            case "error":
            case "argument":
            case "root":
            default:
                throw new Error(`this shouldn't happen (${ast.annotation} node?!)`)
        }
    }

    private generateArgumentListFromShell(ast: ShellAstNode[]) {
        const args = findASTNodesByType(ast, "argument")
        this.argumentList = args.map(
            it => it.children.map(ArgumentEditor.convertAstToText).join('')
        )
    }

    private updateShell(forward?: boolean) {
        this.shellHighlighting.innerHTML = this.shellInput.innerHTML
        const original = this.shellInput.innerHTML

        ArgumentEditor.stripBasicStyleElements(this.shellHighlighting)

        const newHTML = this.shellHighlighting.innerHTML
        this.shellHighlighting.innerHTML = newHTML

        if (newHTML !== original) {
            // setting innerHTML tends to force the cursor to the start of the div.
            // that's really bad, so we're going to use the style stripper and
            // not consolidate the #text (may still cause shifting though)
            ArgumentEditor.stripBasicStyleElements(this.shellInput)
        }

        const syntax = new ShellSyntax(this.understoodVariables)
        const {nodes, hasAnyError} = syntax.parseRoot(this.shellHighlighting)
        if (debugInterface.logASTs) console.info("ast!", nodes)
        for (const astNode of nodes) this.applyHighlighting(astNode)
        if (forward) {
            this.prefShell = true
            this.shellText = this.shellInput.innerText
            if (hasAnyError) {
                if (debugInterface.logASTs)
                    console.info("ast contains errors, not trying conversion")
            } else {
                this.generateArgumentListFromShell(nodes)
                this.flushList()
            }
            this.dispatchChange()
        }
    }

    private renumberListItem(itemEl: HTMLElement, newIndex: number) {
        itemEl.dataset.newIndex = newIndex.toString()
        const editor = itemEl.querySelector(".-edit-stack-editor") as HTMLElement
        editor.ariaLabel = argumentAria.replace("{}", (newIndex + 1).toString())
        const insertButton = itemEl.nextElementSibling as HTMLElement
        const nextIndex = newIndex + 1
        insertButton.dataset.spliceIndex = nextIndex.toString()
        if (!insertButton) throw new Error("inconsistent state: insert button not found")
        insertButton.querySelector("img")!.alt = gutterAria.replace("{}", nextIndex.toString())
    }

    private applyNumberings() {
        this.argListEl.querySelectorAll("[data-new-index]").forEach(el => {
            if (!(el instanceof HTMLElement)) return
            el.dataset.index = el.dataset.newIndex
            delete el.dataset.newIndex
        })
    }

    private deleteListItem(at: number) {
        const oldLength = this.argumentList.length
        this.argumentList.splice(at, 1)
        this.backPropagateShell()
        this.dispatchChange()

        if (this.argumentList.length === 0) return this.flushList()

        // Yeet the DOM parts
        const deletedItem = this.argListEl.querySelector(`[data-index="${at}"]`)
        const deletedButton = this.argListEl.querySelector(`[data-splice-index="${at + 1}"]`)
        deletedItem?.remove()
        deletedButton?.remove()
        if (!(deletedItem && deletedButton)) {
            console.error(`...which element did you click again?`)
            return this.flushList()
        }
        for (let i = at + 1, j = at; i < oldLength; i++, j++) {
            const it = this.argListEl.querySelector(`[data-index="${i}"]`)
            if (!it) {
                console.error(`missing renumbering target ${i} (to be moved to ${j}); nuking it`)
                return this.flushList()
            }
            this.renumberListItem(it as HTMLElement, j)
        }
        this.applyNumberings()
    }

    private insertListItem(at: number, initialText: string) {
        const oldLength = this.argumentList.length
        this.argumentList.splice(at, 0, initialText)
        this.backPropagateShell()
        this.dispatchChange()

        // The rest of this is UI.

        // We need to throw out the old button anyway if this is the first item
        if (oldLength === 0) return this.flushList()

        const after = this.argListEl.querySelector(`[data-splice-index="${at}"]`)
        if (!after) {
            console.error(`inconsistent state: insert button ${at} not found? ...giving up, let's start over`)
            return this.flushList()
        }
        const item = this.argumentListItem(initialText, at)
        const button = this.insertItemButton(at + 1)
        for (let i = at, j = at + 1; i < oldLength; i++, j++) {
            const theItem = this.argListEl.querySelector(`[data-index="${i}"]`)
            if (!theItem) {
                console.error(`where did argument ${at} go?! ...giving up, let's start over`)
                return this.flushList()
            }
            this.renumberListItem(theItem as HTMLElement, j)
        }
        this.applyNumberings()
        after.after(item, button)
    }

    private insertItemButton(index: number, only?: boolean): HTMLElement {
        const base = only ? emptyListButtonI : gutterButtonI
        const inst = base.cloneNode(true) as HTMLElement
        inst.querySelector("button")!.addEventListener("click", e => {
            const reifiedIndex = inst.dataset.spliceIndex
            if (!reifiedIndex) throw new Error("inconsistent state: insert button missing insertion point")
            this.insertListItem(+reifiedIndex, "")
            const newEditorEl = this.argListEl.querySelector(`[data-index="${reifiedIndex}"] .-edit-stack-editor`) as HTMLElement
            newEditorEl.focus()

            e.stopPropagation()
        })
        if (!only) {
            if (index > 0) inst.querySelector("img")!.alt = gutterAria.replace("{}", index.toString())
            else inst.querySelector("img")!.alt = gutterAria1st
        }
        inst.dataset.spliceIndex = index.toString()

        return inst
    }

    private argumentListItem(initialText: string, index: number): HTMLElement {
        const inst = itemI.cloneNode(true) as HTMLElement
        const editor = inst.querySelector(".-edit-stack-editor") as HTMLElement
        const deleteBtn = inst.querySelector(".-delete") as HTMLButtonElement
        editor.ariaLabel = argumentAria.replace("{}", (index + 1).toString())
        editor.innerText = initialText
        const collapse = () => {
            console.info("blur", editor.innerText, inst)
            editor.innerText = stripArgListInput(editor.innerText)
        }
        editor.addEventListener("keydown", ev => {
            // TODO: Document these!
            const actualIndex = inst.dataset.index
            if (!actualIndex) throw new Error("inconsistent state: entry missing index")
            if (ev.key === "Enter") {
                // insert
                const next = +actualIndex + 1
                this.insertListItem(next, "")
                const newEditorEl = this.argListEl.querySelector(`[data-index="${next}"] .-edit-stack-editor`) as HTMLElement
                newEditorEl.focus()
                ev.preventDefault()
                ev.stopPropagation()
                return
            }

            // function() is not allowed here because that would clobber the meaning of `this`
            const deleteIt = (then: number) => {
                this.deleteListItem(+actualIndex)

                if (this.argumentList.length === 0) {
                    const theButton = this.argListEl.querySelector(`.alone-insert-gutter-button`) as HTMLElement
                    theButton?.focus()
                } else {
                    then = then < 0
                        ? 0
                        : then >= this.argumentList.length
                            ? this.argumentList.length - 1
                            : then
                    const newEditorEl = this.argListEl.querySelector(`[data-index="${then}"] .-edit-stack-editor`) as HTMLElement
                    newEditorEl.focus()
                }

                ev.preventDefault()
                ev.stopPropagation()
            }

            const isBasicallyEmpty = !!editor.innerText.match(/^[\r\n]*$/)
            if (ev.key === "Backspace" && isBasicallyEmpty) {
                return deleteIt(+actualIndex - 1)
            }
            if (ev.key === "Delete" && isBasicallyEmpty) {
                return deleteIt(+actualIndex)
            }
            if (ev.key === "ArrowUp" && ev.ctrlKey && +actualIndex > 0) {
                const newEditorEl = this.argListEl.querySelector(`[data-index="${+actualIndex - 1}"] .-edit-stack-editor`) as HTMLElement
                newEditorEl.focus()
                ev.preventDefault()
                ev.stopPropagation()
                return
            }
            if (ev.key === "ArrowDown" && ev.ctrlKey && +actualIndex < this.argumentList.length - 1) {
                const newEditorEl = this.argListEl.querySelector(`[data-index="${+actualIndex + 1}"] .-edit-stack-editor`) as HTMLElement
                newEditorEl.focus()
                ev.preventDefault()
                ev.stopPropagation()
                return
            }
        })
        editor.addEventListener("input", () => {
            this.prefShell = false
            console.info(`input`, editor.innerText, inst)
            const actualIndex = inst.dataset.index
            if (!actualIndex) throw new Error("inconsistent state: entry missing index")
            this.argumentList[+actualIndex] = stripArgListInput(editor.innerText)
            this.backPropagateShell()
            this.dispatchChange()
        })
        editor.addEventListener("blur", collapse)
        editor.addEventListener("paste", collapse)
        deleteBtn.addEventListener("click", e => {
            e.stopPropagation()
            const actualIndex = inst.dataset.index
            if (!actualIndex) throw new Error("inconsistent state: entry missing index")
            const idxN = +actualIndex
            this.deleteListItem(idxN)

            if (this.argumentList.length === 0) return

            const next = idxN >= this.argumentList.length ? this.argumentList.length - 1 : idxN
            const newEditorEl = this.argListEl.querySelector(`[data-index="${next}"] .-edit-stack-editor`) as HTMLElement
            newEditorEl.focus()
        })
        inst.dataset.index = index.toString()
        return inst
    }

    /**
     * start over from scratch with the element list.
     * @private
     */
    private flushList() {
        this.argListEl.innerHTML = ''

        if (this.argumentList.length === 0) {
            this.argListEl.appendChild(
                this.insertItemButton(0, true)
            )
            return
        }

        this.argListEl.appendChild(this.insertItemButton(0))
        for (let i = 0; i < this.argumentList.length; i++) {
            this.argListEl.appendChild(this.argumentListItem(this.argumentList[i]!, i))
            this.argListEl.appendChild(this.insertItemButton(i + 1))
        }
    }

    private backPropagateShell() {
        this.prefShell = false

        const shellChunks: string[] = []

        for (const argument of this.argumentList) {
            let string = false
            let argBuild = ""
            for (const char of argument) {
                if (!string && char.match(/[\s'"]/)) {
                    string = true
                }
                if (char === '"') {
                    argBuild += `"'"'"`
                } else {
                    argBuild += char
                }
            }
            if (string) argBuild = `"${argBuild}"`
            if (argBuild === "") argBuild = `""`
            shellChunks.push(argBuild)
        }

        this.shellText = shellChunks.join(' ')
        this.shellInput.innerText = this.shellText

        this.updateShell(false)
    }

    getData(): ArgumentEditorUpdateData {
        return {
            args: this.argumentList,
            shell: this.shellText,
            shellPref: this.prefShell
        }
    }

    private dispatchChange() {
        this.onChangedEvent.forEach(it => it(this.getData()))
    }

    onChanged(act: ArgumentEditorOnChangeEvent) {
        this.onChangedEvent.push(act)
    }

    setArguments(args: string[]) {
        this.argumentList = [...args]
        this.flushList()
        this.backPropagateShell()
    }

    static conjure(slot: HTMLElement): ArgumentEditor {
        const actualElement = containerI.cloneNode(true) as HTMLElement
        slot.replaceWith(actualElement)
        return new ArgumentEditor(actualElement)
    }
}

export {ArgumentEditor}