function svg(strings: TemplateStringsArray, ...values: any[]): string {
    const result = strings.map(
        (value, index, arry) => index === arry.length - 1 ? value : value + values[index].toString()
    ).join("")
    return "data:image/svg+xml;base64," + btoa(result)
}

