/// <reference path="./common.d.ts" />

import style from './landing.css' with {type: 'css'}
import "./library/recipe.ts"
import {setNotificationRoot, SimpleNotification} from "./notifs.ts"
import {APPLICATION_HTML, ICON_ERROR, ICON_HOURGLASS, INCOMPATIBLE_HTML, type RootComponents} from "./page_content.ts"
import replacer from "./components/replacer.ts"
import "./runtime/yard_shunter.ts"
import {beginRuntime} from "./runtime/recipe_runtime.ts"
import debugInterface from "./debug_interface.ts"
import {loadFromURL} from "./library/the_library.ts"

if (!document.adoptedStyleSheets.includes(style))
    document.adoptedStyleSheets.push(style)

document.body.classList.remove("preload")

function checkCompatibility() {
    try {
        const expected: any[] = [
            HTMLDialogElement,
            WebAssembly,
            fetch,
            Promise.allSettled,
            TextDecoder,
            TextEncoder,
            Object.entries,
            File,
        ]
        if (!expected.every(it => it)) {
            return false
        }
    } catch (error) {
        console.info(error)
        return false
    }
    return true
}

if (!checkCompatibility()) {
    document.body.innerHTML = INCOMPATIBLE_HTML
    throw new Error("Browser is not compatible")
}

document.body.innerHTML = APPLICATION_HTML

const components: RootComponents = Object.fromEntries(replacer(document.body)) as unknown as RootComponents
components.recipeSelectorBtn.attach(components.recipeSelector)
debugInterface.root = components

const el = {
    notifications: document.getElementById("notifications")! as HTMLElement,
    drop: document.getElementById('drop')! as HTMLElement,
    dropInput: document.getElementById('drop-input')! as HTMLInputElement,
}

let loadingNotif: SimpleNotification | null = null

async function onload() {
    // Don't hold up the `load` event on the document.
    await beginRuntime(components.ioPanel)
    await loadFromURL()

    console.log("Setup complete")
    loadingNotif?.remove()
}

setNotificationRoot(el.notifications)

loadingNotif = new SimpleNotification(ICON_HOURGLASS, "Running initial setup").make()
if (document.readyState === 'complete') {
    // noinspection JSIgnoredPromiseFromCall
    onload()
} else {
    window.addEventListener('load', onload)
}

window.addEventListener("error", evt => {
    new SimpleNotification(ICON_ERROR, `Error`).make().setTextTainted(`${evt.error}`)
})

function handleDrop(ev: DragEvent) {
    ev.preventDefault()
    const files = [...ev.dataTransfer!.items]
    const entries = files
        .filter(
            it => it && (it.webkitGetAsEntry && it.webkitGetAsEntry() || it.getAsEntry && it.getAsEntry())?.isFile
        )
        .map(it => it.getAsFile())
        .filter(it => it !== null)
    entries.forEach(components.ioPanel.addFile.bind(components.ioPanel))
    components.ioPanel.refresh()
    el.drop.classList.remove("-hint")
}

// Set up the dropzone
el.drop.addEventListener("click", () => el.dropInput.click())
el.drop.addEventListener("drop", handleDrop)
window.addEventListener("drop", e => {
    console.log('window', e)
    // thanks MDN https://developer.mozilla.org/en-US/docs/Web/API/HTML_Drag_and_Drop_API/File_drag_and_drop
    // el.drop.classList.remove("-hint")
    if ([...e.dataTransfer!.items].some((item) => item.kind === "file")) {
        e.preventDefault()
    }
})
el.drop.addEventListener("dragover", e => {
    const transfer = e.dataTransfer!
    const fileItems = [...transfer.items].filter(
        (item) => item.kind === "file",
    )
    if (fileItems.length > 0) {
        e.preventDefault()
        transfer.dropEffect = "copy"
    }
})
window.addEventListener("dragover", e => {
    const transfer = e.dataTransfer!
    const fileItems = [...transfer.items].filter(
        (item) => item.kind === "file",
    )
    if (fileItems.length > 0) {
        e.preventDefault()
        if (!el.drop.contains(e.target as Node)) {
            transfer.dropEffect = "none"
        }
        el.drop.classList.add("-hint")
    } else {
        el.drop.classList.remove("-hint")
    }
})
el.dropInput.addEventListener("change", e => {
    const target = e.target as HTMLInputElement
    for (const file of target.files!) {
        components.ioPanel.addFile(file)
    }
    components.ioPanel.refresh()
    target.value = ""
})
window.addEventListener("dragleave", () => el.drop.classList.remove("-hint"))
window.addEventListener("dragend", () => el.drop.classList.remove("-hint"))
