import type {Subscription} from "./common.d.ts"
import {FFmpeg} from "@ffmpeg/ffmpeg"
import {ProgressNotification} from "./notifs.ts"
import {bytes} from "./util.ts"

const baseURL = "./vendor/ffmpeg-core"
const workerBaseURL = "./vendor/ffmpeg-ffmpeg"

let coreURL: string | null = null
let coreFetchEvt: Subscription<string>[] | null = null
let wasmURL: string | null = null
let wasmFetchEvt: Subscription<string>[] | null = null
let workerURL: string | null = null
let workerFetchEvt: Subscription<string>[] | null = null

function getFileWithProgress(url: string, mime: string, progress: (ev: ProgressEvent) => void): Promise<string> {
    return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest()
        xhr.onprogress = progress
        xhr.onload = ev => {
            const buf: Blob = xhr.response
            const typed = new Blob([buf], {type: mime})
            resolve(URL.createObjectURL(typed))
        }
        xhr.onerror = ev => {
            reject(ev)
        }
        xhr.open("GET", url, true)
        xhr.responseType = "blob"
        xhr.send()
    })
}

export async function getCore(progress: (ev: ProgressEvent) => void): Promise<string> {
    if (coreURL) return coreURL
    if (coreFetchEvt) return new Promise((resolve, reject) => coreFetchEvt!.push({
        resolve: resolve,
        reject: reject
    }))
    coreFetchEvt = []
    try {
        coreURL = await getFileWithProgress(`${baseURL}/ffmpeg-core.js`, 'text/javascript', progress)
        coreFetchEvt.forEach(it => it.resolve(coreURL!))
    } catch (e) {
        coreFetchEvt.forEach(it => it.reject(e))
        throw e
    } finally {
        coreFetchEvt = null
    }
    return coreURL
}

export async function getWasm(progress: (ev: ProgressEvent) => void): Promise<string> {
    if (wasmURL) return wasmURL
    if (wasmFetchEvt) return new Promise((resolve, reject) => wasmFetchEvt!.push({
        resolve: resolve,
        reject: reject
    }))
    wasmFetchEvt = []
    try {
        wasmURL = await getFileWithProgress(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm', progress)
        wasmFetchEvt.forEach(it => it.resolve(wasmURL!))
    } catch (e) {
        wasmFetchEvt.forEach(it => it.reject(e))
        throw e
    } finally {
        wasmFetchEvt = null
    }
    return wasmURL
}

export async function getWorker(): Promise<string> {
    if (workerURL) return workerURL
    if (workerFetchEvt) return new Promise((resolve, reject) => workerFetchEvt!.push({
        resolve: resolve,
        reject: reject
    }))
    workerFetchEvt = []
    try {
        const [_worker, _const, _errors] = await Promise.all([
            fetch(`${workerBaseURL}/worker.js`)
                .then(it => it.text()),
            fetch(`${workerBaseURL}/const.js`)
                .then(it => it.blob()),
            fetch(`${workerBaseURL}/errors.js`)
                .then(it => it.blob())
        ])
        const typedConst = new Blob([_const], {type: "text/javascript"})
        const typedErrors = new Blob([_errors], {type: "text/javascript"})
        const constURI = URL.createObjectURL(typedConst)
        const errorsURI = URL.createObjectURL(typedErrors)
        const patched = _worker
            .replace(/(from ")\.\/const.js(")/, `$1${constURI}$2`)
            .replace(/(from ")\.\/errors.js(")/, `$1${errorsURI}$2`)
        workerURL = URL.createObjectURL(new Blob([patched], {type: "text/javascript"}))
        console.info("Patched worker script available at", workerURL)
        workerFetchEvt.forEach(it => it.resolve(workerURL!))
    } catch (e) {
        workerFetchEvt.forEach(it => it.reject(e))
        throw e
    } finally {
        workerFetchEvt = null
    }
    return workerURL!
}

const noop = () => {
}

export async function newFFmpeg(preload: (ffmpeg: FFmpeg) => void): Promise<FFmpeg> {
    const ffmpeg = new FFmpeg()
    preload(ffmpeg)
    await ffmpeg.load({
        coreURL: await getCore(noop),
        wasmURL: await getWasm(noop),
        classWorkerURL: await getWorker(),
    })
    return ffmpeg
}

export async function fetchIt(icon: string) {
    const notif = new ProgressNotification(icon, "Downloading ffmpeg...").make()

    let prog1 = 0
    let total1: number | null = null
    let prog2 = 0
    let total2: number | null = null

    function updateProgress() {
        const allProgress = [prog1, prog2]
        const allTotal = [total1, total2]
        const total = allTotal.some(it => it === null)
            ? null
            : allTotal.reduce((l, r) => l! + r!, 0)
        const prog = allProgress.reduce((l, r) => l + r, 0)
        notif.update(
            prog,
            total
        )
        if (total === null)
            notif.setText(`Downloading ffmpeg:<br>${bytes(prog1 + prog2)}?`)
        else
            notif.setText(`Downloading ffmpeg:<br>${bytes(prog1 + prog2)}/${bytes(total)}`)
    }

    const prom1 = getCore(ev => {
        total1 = ev.lengthComputable ? ev.total : null
        prog1 = ev.loaded
        updateProgress()
    })
    const prom2 = getWasm(ev => {
        total2 = ev.lengthComputable ? ev.total : null
        prog2 = ev.loaded
        updateProgress()
    })
    const prom3 = getWorker()

    await Promise.all([prom1, prom2, prom3])
    console.info("!! download completed")
    notif.remove()
}

//@ts-ignore
window.newFFmpeg = newFFmpeg