import {ComplexRecipeFormat, SimpleRecipeFormat} from "../library/metadata.ts"
import {RecipeImpl} from "../library/recipe.ts"
import type {RecipeCommon, rStep} from "../library/recipe_raw_types.d.ts"

export interface SimpleRecipeData extends RecipeCommon {
    parser: "simple"

    shellHint?: string
    argumentList: string[]

    fileExtension?: string
    fileExtensionStyle: "append" | "replace"
}

export const DEFAULT_SIMPLE_RECIPE: SimpleRecipeData = {
    version: SimpleRecipeFormat.current,
    parser: "simple",
    name: "",
    argumentList: ["-i", "${in}", "${out}"],
    fileExtensionStyle: "append",
}

export function convertSimpleToRecipe(data: SimpleRecipeData): RecipeImpl {
    // input == ${file}
    // input filename == ${name}
    const steps: rStep[] = [
        {
            type: "set",
            vars: {
                "in": "${file}",
                "out": data.fileExtension ? `out.${data.fileExtension}` : "out"
            }
        },
        {
            type: "ffmpeg",
            cmd: [...data.argumentList]
        },
    ]
    if (data.fileExtension) {
        if (data.fileExtensionStyle === "replace") {
            steps.push({
                type: "subst",
                input: "${name}",
                pattern: "(.)\\.([^\\s.]+)$|(.)$",
                repl: `$1$3.${data.fileExtension}`,
                flagI: false,
                flagM: false,
                flagS: false,
                output: "outName"
            })
        } else {
            steps.push({
                type: "subst",
                input: "${name}",
                pattern: "$",
                repl: `.${data.fileExtension}`,
                flagI: false,
                flagM: false,
                flagS: false,
                output: "outName"
            })
        }
    } else {
        steps.push({
            type: "set",
            vars: {
                "outName": "${name}"
            }
        })
    }
    steps.push({
        type: "out",
        name: "${outName}",
        file: "${out}"
    })
    return RecipeImpl.parse({
        version: ComplexRecipeFormat.current,
        parser: "complex",
        author: data.author ?? "Unknown Author",
        shortDescription: data.shortDescription,
        longDescription: data.longDescription ?? "",
        name: data.name,
        steps: steps
    })
}