import type {CookingState, Kitchen, Recipe} from "../library/recipe_types.d.ts"
import {fetchIt, newFFmpeg} from "../kitchen.ts"
import {ICON_ERROR, ICON_HOURGLASS} from "../page_content.ts"
import type {FFmpeg} from "@ffmpeg/ffmpeg"
import type {Codec, Pairing, TaggedFile} from "../common.d.ts"
import {fetchFile} from "@ffmpeg/util"
import {type IOPanel} from "../components/io.ts"
import compile from "../library/recipe_compilers.ts"
import {bytes} from "../util.ts"
import type {SupportedRawTypes} from "../library/recipe_raw_types.d.ts"
import {SimpleNotification} from "../notifs.ts"

let currentRecipe: Recipe | null = null
const onRecipeChangedH: ((newRecipe: Recipe | null) => void)[] = []

const MAX_WORKER_COUNT = Math.max(4, navigator.hardwareConcurrency - 1)
let analysisWorker: FFmpeg | undefined = undefined

export const runningJobs: Map<string, FFmpeg> = new Map()

export const analysisQueue: Pairing[] = []
export const processingQueue: Pairing[] = []

const delay = (millis: number) => new Promise(resolve => setTimeout(resolve, millis))
let ioUI!: IOPanel
let poke!: (file: Pairing) => void
let pokeAll!: () => void

export function getCurrentRecipe() {
    return currentRecipe
}

function failFile(file: TaggedFile, reason: any) {
    console.error(reason)
    file.state = "unusable"
    file.description = `can't process this file: ${reason}`
    pokeAll()
    return
}

function matchStrOrNull(s: string, re: RegExp): string | null {
    const result = s.match(re)
    if (!result || !result[1]) return null
    return result[1]
}

function matchNumOrNull(s: string, re: RegExp): number | null {
    const result = s.match(re)
    if (!result || !result[1]) return null
    const value = parseFloat(result[1])
    if (isNaN(value)) return null
    return value
}

class AudioCodec implements Codec {
    name: string
    type: "audio"
    channels: number
    duration: number | null
    bitRate: number | null

    constructor(probe: string) {
        this.type = "audio"
        this.name = matchStrOrNull(probe, /codec_name=(.+)/)!
        this.channels = matchNumOrNull(probe, /channels=(\d+)/)!
        this.duration = matchNumOrNull(probe, /duration=(\d+(?:\.\d+)?)/)
        this.bitRate = matchNumOrNull(probe, /bit_rate=(\d+(?:\.\d+)?)/)
    }

    describe(): string {
        let channelName: string
        switch (this.channels) {
            case 0:
                channelName = "uhh"
                break
            case 1:
                channelName = "mono"
                break
            case 2:
                channelName = "stereo"
                break
            default:
                channelName = "surround?"
                break
        }
        const durationStr = this.duration === null ? "unknown duration" : `${this.duration.toFixed(2)}s`
        return `${this.name} audio: ${durationStr} / ${this.channels} channel${this.channels == 1 ? '' : 's'} (${channelName}) @ ${this.bitRate} bps`
    }
}

class VideoCodec implements Codec {
    name: string
    type: "video"
    width: number
    height: number
    duration: number | null
    bitRate: number | null

    constructor(probe: string) {
        this.type = "video"
        this.name = matchStrOrNull(probe, /codec_name=(.+)/)!
        this.width = matchNumOrNull(probe, /width=(\d+)/)!
        this.height = matchNumOrNull(probe, /height=(\d+)/)!
        this.duration = matchNumOrNull(probe, /duration=(\d+(?:\.\d+)?)/)
        this.bitRate = matchNumOrNull(probe, /bit_rate=(\d+(?:\.\d+)?)/)
    }

    describe(): string {
        const durationStr = this.duration === null ? "unknown duration" : `${this.duration.toFixed(2)}s`
        return `${this.name} video: ${durationStr} / ${this.width}x${this.height} @ ${this.bitRate} bps`
    }
}

class SubtitleCodec implements Codec {
    name: string
    type: "subtitle"

    constructor(probe: string) {
        this.type = "subtitle"
        this.name = matchStrOrNull(probe, /codec_name=(.+)/)!
    }

    describe(): string {
        return `${this.name} subtitle track`
    }
}

const knownCodecs = {
    audio: AudioCodec,
    video: VideoCodec,
    subtitle: SubtitleCodec,
} as const

function analyzeStreams(probe: string, file: TaggedFile) {
    const regexp = /\[STREAM]\s*([\w\W]*?)\s*\[\/STREAM]/gm
    const chunks: string[] = []
    let m: RegExpExecArray | null
    while ((m = regexp.exec(probe)) !== null) {
        if (m.index === regexp.lastIndex) regexp.lastIndex++
        chunks.push(m[1]!)
    }
    const results: Codec[] = []
    for (const chunk of chunks) {
        const type = chunk.match(/codec_type=(\w+)/)
        if (!type || !type[1]) {
            console.warn(`can't determine codec type for a chunk in ${file.id}`)
            continue
        }
        const codec = knownCodecs[type[1] as keyof typeof knownCodecs]
        if (!codec) {
            console.warn(`not interpreting codec of type ${type[1]}`)
            continue
        }
        results.push(new codec(chunk))
    }
    return results
}

async function analyzeOne(file: TaggedFile, pair: Pairing): Promise<boolean> {
    if (file.state !== "analyze") {
        console.warn(`file in wrong state (${file.state}) landed in analysis queue:`, file, file)
        return false
    }
    file.state = "analyzing"
    file.description = "Analysis in progress..."
    poke(pair)
    try {
        await analysisWorker!.writeFile(file.id, await fetchFile(file.file))
        const statFilename = `${file.id}-stat.txt`
        await analysisWorker!.ffprobe([
            '-v', 'error',
            '-show_entries',
            'stream',
            file.id,
            '-o', statFilename
        ])
        const data = new TextDecoder().decode(await analysisWorker!.readFile(statFilename) as Uint8Array)
        const streams = analyzeStreams(data, file)

        file.state = "ready"
        const desc: string[] = []
        desc.push(bytes(file.file.size))
        if (streams.length === 0) {
            failFile(file, "no a/v media detected")
            return false
        }
        for (const stream of streams) {
            desc.push(stream.describe())
        }
        file.description = desc.join('\n')
        pokeAll()
        return true
    } catch (e) {
        failFile(file, e)
        return false
    } finally {
        void analysisWorker!.deleteFile(file.id)
    }
}

async function analysisJob() {
    // there's no coming back from this. it's basically setInterval
    // noinspection InfiniteLoopJS
    while (true) {
        await delay(10)
        const file = analysisQueue.shift()
        if (!file) continue
        if (file.inp && file.inp.state === "analyze") {
            if (await analyzeOne(file.inp, file)) {
                processingQueue.push(file)
            }
        }
        if (file.out && file.out.state === "analyze") {
            await analyzeOne(file.out, file)
        }
    }


}

/**
 * ## Default Variables
 * - `${file}`: file name IN the container (usually a UUID)
 * - `${name}`: file name OUTSIDE the container (usually what you want to do to derive the result name)
 */
async function executionJob(n: number) {
    const label = `Worker${n}`
    main: // noinspection InfiniteLoopJS
        while (true) {
            console.info(label, "Now waiting for work")
            let job: Pairing | undefined
            while (true) {
                await delay(100)
                if (!currentRecipe) continue
                job = processingQueue.shift()
                if (!job) continue
                break
            }

            const input = job.inp

            if (!ioUI.getFile(job.id)) {
                console.warn(label, `work already expired for id ${job.id}`)
                continue
            }
            if (input.state !== "ready") {
                console.warn(label, "refusing to start work because input is not ready", job)
                continue
            }

            const row = ioUI.getRow(job.id)
            console.info(label, "woke up! now working on", input)
            ioUI.deleteOutput(job)
            row?.updateBuildLog("[initializing runner]", label)
            const recipe = currentRecipe
            const ffmpeg = await newFFmpeg(f => {
                f.on("log", e => {
                    row?.updateBuildLog(e.message, label)
                })
            })
            runningJobs.set(job.id, ffmpeg)
            let state: CookingState | undefined
            try {
                row?.updateBuildLog("[loading input]", label)

                const ext = input.file.name.split(".")
                const internalFileName = ext.length > 1 ? `${input.id}.${ext.at(-1)}` : input.id
                if (!runningJobs.has(job.id)) {
                    row?.updateBuildLog(`abandoning execution (apparently terminated?)`, label)
                    continue
                }
                await ffmpeg.writeFile(internalFileName, await input.file.bytes())

                state = {
                    input: input,
                    output: null,
                    recipe: recipe,
                    variables: {
                        "file": internalFileName,
                        "name": input.file.name
                    }
                }
                const kitchen: Kitchen = {
                    ffmpeg: ffmpeg,
                    logback: data => row?.updateBuildLog(data, label)
                }

                for (const [i, step] of recipe.steps.entries()) {
                    if (!runningJobs.has(job.id)) {
                        row?.updateBuildLog(`abandoning execution (apparently terminated?)`, label)
                        continue main
                    }
                    row?.updateBuildLog(`step ${i + 1}: ${step.type}...`, label)
                    await step.execute(state, kitchen)
                }
                row?.updateBuildLog(`finishing`, label)
                if (state.output) {
                    job.out = state.output
                    job.out.state = "analyze"
                    poke(job)
                    analysisQueue.push(job)
                }
            } catch (e) {
                row?.updateBuildLog(`error! ${e}`, label)
                console.warn("Crash state:", state)
                console.error(e)
            } finally {
                ffmpeg.terminate()
                runningJobs.delete(job.id)
            }
        }

}

export async function beginRuntime(ui: IOPanel) {
    poke = ui.refreshOne.bind(ui)
    pokeAll = ui.refresh.bind(ui)
    ioUI = ui
    await fetchIt(ICON_HOURGLASS)
    analysisWorker = await newFFmpeg(() => {
    })
    console.info(`Starting analysis worker`)
    void analysisJob()
    console.info(`Starting ${MAX_WORKER_COUNT} execution workers`)
    for (let i = 0; i < MAX_WORKER_COUNT; i++) void executionJob(i)
    console.info(`Runtime setup completed`)
}

export function setRecipe(newRecipe: Recipe | null): void {
    if (newRecipe !== currentRecipe) {
        currentRecipe = newRecipe
        for (const [id, ffmpeg] of runningJobs.entries()) {
            ffmpeg.terminate()
        }
        runningJobs.clear()
        processingQueue.length = 0
        for (const file of ioUI.inputs) {
            ioUI.deleteOutput(file)
            processingQueue.push(file)
        }
        onRecipeChangedH.forEach(it => it(newRecipe))
    }
}

export function compileAndSetRecipe(recipe: SupportedRawTypes | null): boolean {
    if (recipe === null) {
        setRecipe(recipe)
        return true
    }
    try {
        const compiled = compile(recipe)
        setRecipe(compiled)
        return true
    } catch (e) {
        const notif = new SimpleNotification(ICON_ERROR, `Recipe compile failed`).make()
        notif.setTextTainted(`Recipe compile failed: ${e}`)
        setTimeout(() => notif.remove(), 2000)
        return false
    }
}

export function onRecipeChanged(callback: (newRecipe: Recipe | null) => void) {
    onRecipeChangedH.push(callback)
}
