/*
turn the various types of recipe into the standardized format
for running
*/

import type {SupportedRawTypes} from "./recipe_raw_types.d.ts"
import {RecipeImpl} from "./recipe.ts"
import {convertSimpleToRecipe} from "../simple/simple_types.ts"

export default function compile(data: SupportedRawTypes): RecipeImpl {
    switch (data.parser) {
        case "complex":
            return RecipeImpl.parse(data)
        case "simple":
            return convertSimpleToRecipe(data)
        default:
            throw new Error(`not sure how to convert ${data.parser} to recipe`)
    }
}