import {html1} from "./component_utilities.ts"
import replacer, {createReplaceTag} from "./replacer.ts"
import type {IRecipeSelector, RecipeSelectorPage} from "./recipe_selector_types.d.ts"
import type { LibraryCheckout } from "../library/the_library.ts"
import PageRecipeViewer from "./editor/viewer.ts"
import PageSimpleEdit from "./editor/simple_edit.ts"

const CONTAINER = html1(`<!---->
<dialog id="recipe-selector" tabindex="-1" aria-label="Recipe selector" closedby="none">
</dialog>
`)

export const RecipeSelectorPages = {
    root: "page-root",
    simpleEdit: "page-simple-edit",
    viewer: "page-viewer"
}
export type RecipeSelectorPageName = keyof typeof RecipeSelectorPages

export default class RecipeSelector implements Swappable, IRecipeSelector {
    private readonly wrap: HTMLDialogElement
    private pageData!: RecipeSelectorPage

    pageName: RecipeSelectorPageName = "root"
    private goBack: RecipeSelectorPageName[] = []

    constructor(
        wrap: HTMLDialogElement,
    ) {
        this.wrap = wrap
        this.loadPage("root")
    }

    openViewer(checkout: LibraryCheckout, replaceCurrent: boolean): void {
        const targetNode = document.createElement("div")
        this.wrap.replaceChildren(targetNode)

        this.pageData?.teardown()
        this.pageData = PageRecipeViewer.conjureVariant(targetNode, checkout)
        this.pageData.attach(this)
        if (!replaceCurrent) {
            this.goBack.push(this.pageName)
        }
        this.pageName = "viewer"
    }

    openSimpleEdit(checkout: LibraryCheckout | undefined, replaceCurrent: boolean): void {
        const targetNode = document.createElement("div")
        this.wrap.replaceChildren(targetNode)

        this.pageData?.teardown()
        this.pageData = checkout ? PageSimpleEdit.conjureFromCheckout(targetNode, checkout) : PageSimpleEdit.conjure(targetNode)
        this.pageData.attach(this)
        if (!replaceCurrent) {
            this.goBack.push(this.pageName)
        }
        this.pageName = "simpleEdit"
    }

    pushLoadPage(newPage: RecipeSelectorPageName) {
        this.goBack.push(this.pageName)
        this.loadPage(newPage)
    }

    back() {
        let newPage = this.goBack.pop()
        if (!newPage) {
            console.error("nothing to go back to. assuming root?")
            newPage = "root"
        }
        this.loadPage(newPage)
    }

    loadPage(newPage: RecipeSelectorPageName) {
        this.pageData?.teardown()

        this.pageName = newPage
        const pageName = RecipeSelectorPages[newPage]
        this.wrap.replaceChildren(createReplaceTag(pageName, "page"))
        this.pageData = replacer(this.wrap).get("page") as RecipeSelectorPage
        this.pageData.attach(this)
    }

    close() {
        this.pageData?.teardown()
        this.wrap.close()
    }

    show() {
        this.goBack.length = 0
        this.pageName = "root"
        this.loadPage("root")
        this.wrap.showModal()
    }

    /**
     * this is kinda like the default constructor. it's nothing special and assumes you want to create something new
     * @param slot
     */
    static conjure(slot: HTMLElement): RecipeSelector {
        const actualElement = CONTAINER.cloneNode(true) as HTMLDialogElement
        slot.replaceWith(actualElement)
        return new RecipeSelector(actualElement)
    }
}