import {ICON_CLEAR, ICON_DOWNLOAD, ICON_REFRESH} from "../page_content.ts"
import type {AbstractIORow, Pairing, TaggedFile} from "../common.d.ts"
import {html1, html2, html2copy} from "./component_utilities.ts"
import {analysisQueue, processingQueue, runningJobs} from "../runtime/recipe_runtime.ts"

function generateColor(): string {
    const hole = 218 - 182
    let hue = Math.random() * (360 - hole)
    if (hue > hole) hue += hole
    return hue.toFixed(2) + "deg"
}

const INPUT_ROW = html1(`
<div class="input-file">
    <div class="-name">name?</div>
    <button class="-remove"><img src="${ICON_CLEAR}" alt="Remove input"></button>
    <div class="-desc">desc?</div>
</div>
`)
const OUTPUT_ROW = html1(`
<div class="output-file">
    <div class="-name">name?</div>
    <button class="-retry"><img src="${ICON_REFRESH}" alt="Re-run conversion"></button>
    <button class="-download"><img src="${ICON_DOWNLOAD}" alt="Download"></button>
    <div class="-desc">desc?</div>
</div>
`)
const NO_OUTPUT_ROW = html1(`
<div class="output-file no-output-file">
    [no output]
</div>
`)

export class IORow implements AbstractIORow {
    readonly id: string
    readonly el: HTMLElement
    private valid = false
    private onRemovedCallbacks: ((row: IORow) => void)[] = []
    private onRetryCallbacks: ((row: IORow) => void)[] = []
    private onDownloadCallbacks: ((row: IORow) => void)[] = []
    hasOutput: boolean = false

    constructor(container: HTMLElement, id: string, name: string, initialDescription: string) {
        this.id = id
        this.el = document.createElement("li")
        this.el.replaceChildren(
            INPUT_ROW.cloneNode(true),
            NO_OUTPUT_ROW.cloneNode(true),
        )
        const nameEl = this.el.querySelector(".input-file .-name") as HTMLElement
        const descEl = this.el.querySelector(".input-file .-desc") as HTMLElement
        nameEl.innerText = name
        descEl.innerText = initialDescription
        this.el.classList.add("-row")
        container.appendChild(this.el)
        this.el.querySelector(".-remove")?.addEventListener("click", () => {
            this.onRemovedCallbacks.forEach(it => it(this))
        })
        this.el.style.setProperty("--hue", generateColor())
        this.clearOutput()
        this.valid = true
    }

    changeInputDesc(desc: string) {
        const el = this.el.querySelector(".input-file .-desc")! as HTMLElement
        el.innerText = desc
    }

    clearOutput() {
        this.hasOutput = false
        const noOutput = NO_OUTPUT_ROW.cloneNode(true)
        this.el.querySelector(".output-file")?.replaceWith(noOutput)
    }

    updateBuildLog(log: string, ident: string) {
        console.log(`%c${ident}%c ${log}`, "color: #b0b0b0;", "")
        const outputLabel = this.el.querySelector(".output-file.no-output-file") as HTMLElement | undefined
        if (outputLabel) outputLabel.innerText = log
    }

    onRemovedByUser(action: (row: IORow) => void) {
        this.onRemovedCallbacks.push(action)
    }

    onRetriedByUser(action: (row: IORow) => void) {
        this.onRetryCallbacks.push(action)
    }

    onDownloadedByUser(action: (row: IORow) => void) {
        this.onDownloadCallbacks.push(action)
    }

    isValid() {
        return this.valid
    }

    removeVisuals() {
        this.valid = false
        this.el.remove()
    }

    changeOutputDesc(description: string) {
        const el = this.el.querySelector(".output-file .-desc")! as HTMLElement
        if (!el) return
        el.innerText = description
    }

    setOutput(name: string, initialDescription: string) {
        this.hasOutput = true
        const output = OUTPUT_ROW.cloneNode(true) as HTMLElement
        const nameEl = output.querySelector(".-name") as HTMLElement
        const descEl = output.querySelector(".-desc") as HTMLElement
        nameEl.innerText = name
        descEl.innerText = initialDescription
        output.querySelector(".-retry")?.addEventListener("click", () => {
            this.onRetryCallbacks.forEach(it => it(this))
        })
        output.querySelector(".-download")?.addEventListener("click", () => {
            this.onDownloadCallbacks.forEach(it => it(this))
        })
        this.el.querySelector(".output-file")?.replaceWith(output)
    }
}

