export class IOPanel implements Swappable {
    private readonly rows: Map<string, IORow> = new Map()
    private readonly fileList: HTMLUListElement
    private readonly inputManipulators: HTMLElement
    private readonly clearAllBtn: HTMLButtonElement
    private readonly clearInvalidBtn: HTMLButtonElement
    inputs: Pairing[] = []

    constructor(container: HTMLElement) {
        this.fileList = container.querySelector("ul#io") as HTMLUListElement
        this.inputManipulators = container.querySelector("#input-manipulators") as HTMLElement
        this.clearAllBtn = container.querySelector("button#clear-inputs") as HTMLButtonElement
        this.clearAllBtn.addEventListener("click", () => {
            for (const file of [...this.inputs]) {
                this.removeFile(file)
            }
            this.refresh()
        })
        this.clearInvalidBtn = container.querySelector("button#clear-invalid") as HTMLButtonElement
        this.clearInvalidBtn.addEventListener('click', () => {
            this.inputs
                .filter(it => it.inp.state === "unusable")
                .forEach(this.removeFile.bind(this))
            this.refresh()
        })
    }

    refreshRow(row: IORow, file: Pairing) {
        row.changeInputDesc(file.inp.description)
        row.el.dataset.state = file.inp.state
        if (file.out) {
            if (!row.hasOutput) {
                row.setOutput(file.out.file.name, "completed. analysis in progress")
            }
            row.changeOutputDesc(file.out.description)
        }
    }

    refreshOne(file: Pairing) {
        let row = this.getRow(file.id)
        const { inp } = file
        if (!row) {
            row = inp.row = this.newRow(file.id, inp.file.name, inp.description)
            row.onRemovedByUser(() => this.removeFile(file))
        }
        this.refreshRow(row, file)
    }

    refresh() {
        const ids: Set<string> = new Set()
        for (const file of this.inputs) {
            this.refreshOne(file)
            ids.add(file.id)
        }
        for (const row of this.allRows()) {
            if (!ids.has(row.id)) {
                this.removeRow(row.id)
            }
        }
        this.inputManipulators.hidden = this.inputs.length === 0
        this.clearInvalidBtn.hidden = !this.inputs.some(it => it.inp.state === "unusable")
    }

    removeFile(file: Pairing) {
        const idx = this.inputs.indexOf(file)
        if (idx !== -1) this.inputs.splice(idx, 1)
        this.removeRow(file.id)
        runningJobs.get(file.id)?.terminate()
        runningJobs.delete(file.id)
    }

    deleteOutput(file: Pairing) {
        file.out = undefined
        this.getRow(file.id)?.clearOutput()
    }

    addFile(file: File) {
        console.log("+", file)
        const id = crypto.randomUUID()
        const row = this.newRow(id, file.name, "Analysis pending...")
        const item: TaggedFile = {
            file: file,
            id: id,
            description: "Analysis pending...",
            state: "analyze" as const,
            row: row
        }
        const pair = {
            id: id,
            inp: item
        }
        this.inputs.push(pair)
        analysisQueue.push(pair)
        row.onRemovedByUser(() => this.removeFile(pair))
        this.refresh()
    }

    allRows(): IORow[] {
        return this.rows.values().toArray()
    }

    getRow(id: string): IORow | undefined {
        return this.rows.get(id)
    }

    removeRow(id: string) {
        const before = this.rows.get(id)
        if (before) before.removeVisuals()
        this.rows.delete(id)
        this.refresh()
    }

    newRow(id: string, name: string, desc: string): IORow {
        const row = new IORow(this.fileList, id, name, desc)
        row.onRemovedByUser(it => {
            this.removeRow(it.id)
        })
        row.onRetriedByUser(it => {
            runningJobs.get(it.id)?.terminate()
            runningJobs.delete(it.id)
            const pair = this.inputs.find(p => p.id === it.id)
            if (pair) {
                it.clearOutput()
                this.deleteOutput(pair)
                processingQueue.push(pair)
            }
        })
        row.onDownloadedByUser(it => {
            const pair = this.inputs.find(p => p.id === it.id)
            if (pair && pair.out) {
                const file = pair.out.file
                const objUrl = URL.createObjectURL(new Blob([file]))
                const link = document.createElement("a")
                link.href = objUrl
                link.download = pair.out.file.name
                link.style.display = "none"
                document.body.appendChild(link)
                link.click()
                link.remove()
                URL.revokeObjectURL(objUrl)
            }
        })
        this.rows.set(id, row)
        return row
    }

    retryAll() {
        for (const input of this.inputs) {
            this.deleteOutput(input)
            runningJobs.get(input.id)?.terminate()
            runningJobs.delete(input.id)
            processingQueue.push(input)
        }
    }

    static conjure(slot: HTMLElement) {
        const actualElement = html2copy(CONTENTS)
        const parent = slot.parentElement
        if (!parent) throw new Error("Slot is unparented, cannot expand elements")
        slot.replaceWith(...actualElement)
        return new IOPanel(parent)
    }

    getFile(id: string) {
        return this.inputs.find(p => p.id === id)
    }
}