export default class PageSimpleEdit implements RecipeSelectorPage {
    private readonly container: HTMLElement
    private recipeSel!: IRecipeSelector
    private readonly linkedData: SimpleRecipeData
    private readonly writeBackInfo: LibraryCheckoutInfo | undefined
    private readonly titleEl: HTMLInputElement
    private readonly exitDialog: HTMLDialogElement
    private readonly extensionInput: HTMLInputElement
    private readonly filenameAppend: HTMLInputElement
    private readonly saveButton: HTMLButtonElement

    private readonly filenameReplace: HTMLInputElement
    private editor: ArgumentEditor
    private modified: boolean = false

    constructor(container: HTMLElement, data: SimpleRecipeData, writeBackInfo?: LibraryCheckoutInfo) {
        if (data.version < SimpleRecipeFormat.minimum || data.version > SimpleRecipeFormat.current) {
            throw new Error("Import failure: recipe is too old / new")
        }
        this.container = container

        this.linkedData = data
        this.writeBackInfo = writeBackInfo
        this.editor = replacer(container).get("ffmpegCommand") as ArgumentEditor
        this.editor.understoodVariables.push("in", "out")
        this.editor.onChanged(this.argListChanged.bind(this))
        this.titleEl = container.querySelector("input.-recipe-title") as HTMLInputElement
        this.titleEl.addEventListener("input", () => {
            this.linkedData.name = this.titleEl.value
            this.modified = true
        })
        this.titleEl.addEventListener("blur", () => this.titleEl.scroll({top: 0, left: 0, behavior: "smooth"}))
        this.exitDialog = container.querySelector(".-confirm-exit") as HTMLDialogElement
        this.exitDialog.querySelector(".-no")
            ?.addEventListener("click", () => this.exitDialog.close())
        this.extensionInput = container.querySelector(`input[name="extension"]`) as HTMLInputElement
        this.extensionInput.addEventListener("input", () => {
            const result = this.extensionInput.value.trim()
            if (result === "") this.linkedData.fileExtension = undefined
            else this.linkedData.fileExtension = result
            this.modified = true
        })
        const updateExtHandling = (value: "append" | "replace") => {
            this.linkedData.fileExtensionStyle = value
            this.modified = true
        }
        this.filenameAppend = container.querySelector(`input[name="filename-handling"][value="append"]`) as HTMLInputElement
        this.filenameAppend.addEventListener("input", () => updateExtHandling("append"))
        this.filenameReplace = container.querySelector(`input[name="filename-handling"][value="replace"]`) as HTMLInputElement
        this.filenameReplace.addEventListener("input", () => updateExtHandling("replace"))
        this.saveButton = container.querySelector("button.-save-button") as HTMLButtonElement

        this.fillFromData()
    }

    teardown(): void {
    }

    fillFromData() {
        this.editor.setArguments(this.linkedData.argumentList)
        this.titleEl.value = this.linkedData.name
        this.filenameAppend.checked = this.linkedData.fileExtensionStyle !== "replace"
        this.filenameReplace.checked = this.linkedData.fileExtensionStyle === "replace"
        this.extensionInput.value = this.linkedData.fileExtension ?? ""
    }

    argListChanged(data: ArgumentEditorUpdateData) {
        this.linkedData.argumentList = data.args
        this.linkedData.shellHint = data.shellPref ? data.shell : undefined
        this.modified = true
    }

    saveAndExit() {
        let checkout: LibraryCheckout
        if (this.writeBackInfo) {
            checkout = LIBRARY.updateDirect(this.writeBackInfo.key, this.linkedData)
        } else {
            const id = LIBRARY.createNew(this.linkedData, "created")
            checkout = LIBRARY.getByID(id)!
        }
        LIBRARY.save()
        this.recipeSel.openViewer(checkout, true)
    }

    attach(parent: IRecipeSelector): void {
        this.recipeSel = parent

        this.container.querySelector("button.editor-back-button")
            ?.addEventListener("click", () => {
                if (this.modified)
                    this.exitDialog.showModal()
                else
                    this.recipeSel.back()
            })
        this.exitDialog.querySelector(".-yes")
            ?.addEventListener("click", () => this.recipeSel.back())

        this.saveButton.addEventListener("click", () => this.saveAndExit())
    }

    getData() {
        return this.linkedData
    }

    static conjureVariant(slot: HTMLElement, recipeData: SimpleRecipeData, writeBackInfo?: LibraryCheckoutInfo) {
        if (recipeData.parser !== "simple") throw new Error(`Cannot edit this recipe type using the simple editor: ${recipeData.parser}`)
        const actualElement = html2copy(CONTENTS)
        const parent = slot.parentElement
        if (!parent) throw new Error("Slot is unparented, cannot expand elements")
        slot.replaceWith(...actualElement)
        return new PageSimpleEdit(parent, recipeData, writeBackInfo)
    }

    static conjure(slot: HTMLElement): PageSimpleEdit {
        return PageSimpleEdit.conjureVariant(slot, structuredClone(DEFAULT_SIMPLE_RECIPE))
    }

    static conjureFromCheckout(slot: HTMLElement, checkout: LibraryCheckout) {
        return PageSimpleEdit.conjureVariant(slot, structuredClone(checkout.data as SimpleRecipeData), checkout.checkout)
    }
}