import {html1} from "./component_utilities.ts"
import type RecipeSelector from "./recipe_selector.ts"
import {getCurrentRecipe, onRecipeChanged} from "../runtime/recipe_runtime.ts"
import type {Recipe} from "../library/recipe_types.d.ts"

const CONTENTS = html1(`
<button id="recipe-selector-btn">
    <div class="-row-1">
        <span class="-title" role="heading" aria-level="3">Recipe title</span>
        <span class="-byline">by <span class="-author">debugging witch &lt;3</span></span>
    </div>
    <span class="-desc">Recipe short description</span>
    <span class="-hint">Click to change</span>
</button> 
`)

export default class RecipeSelectorButton implements Swappable {
    private wrap: HTMLElement
    private title: HTMLElement
    private author: HTMLElement
    private byline: HTMLElement
    private desc: HTMLElement

    constructor(wrap: HTMLButtonElement) {
        this.wrap = wrap
        this.title = wrap.querySelector(".-title") as HTMLSpanElement
        this.author = wrap.querySelector(".-author") as HTMLSpanElement
        this.desc = wrap.querySelector(".-desc") as HTMLSpanElement
        this.byline = wrap.querySelector(".-byline") as HTMLSpanElement
        onRecipeChanged(this.update.bind(this))
        this.update(getCurrentRecipe())
    }

    attach(recipeSelector: RecipeSelector): void {
        this.wrap.addEventListener("click", () => {
            recipeSelector.show()
        })
    }

    private update(r: Recipe | null) {
        this.byline.hidden = r === null
        this.desc.hidden = r === null
        if (r === null) {
            this.wrap.classList.add("no-recipe")
            this.title.innerText = "No recipe selected"
        } else {
            this.wrap.classList.remove("no-recipe")
            this.title.innerText = r.name
            this.author.innerText = r.author ?? "(unknown)"
            this.desc.innerText = r.longDescription ?? r.shortDescription ?? "no description available"
        }
    }

    static conjure(slot: HTMLElement): RecipeSelectorButton {
        const instance = CONTENTS.cloneNode(true) as HTMLButtonElement
        slot.replaceWith(instance)
        return new RecipeSelectorButton(instance)
    }
}