export function html1(innards: string) {
    const throwaway = document.createElement("div")
    throwaway.innerHTML = innards
    const actualElement = throwaway.firstElementChild! as HTMLElement
    actualElement.remove() // detach from the throwaway element
    return actualElement
}

declare const html2tok: unique symbol
// underlying type: HTMLDivElement
export type html2tok = { readonly [html2tok]: "html2_token_type" }

export function html2(innards: string): html2tok {
    const throwaway = document.createElement("div")
    throwaway.innerHTML = innards
    return throwaway as unknown as html2tok
}

export function html2copy(div: html2tok): ChildNode[] {
    const reified = div as unknown as HTMLDivElement
    return Array.from(reified.cloneNode(true).childNodes)
        .map(it => {
            it.remove()
            return it
        })
}
